programs.sol:
"""Alternatives and punctuation glued to the next item.

This predicts a positive signal for 'or', several translated disjunctions,
and the end-of-document token. Commas fused to a following letter or word
are the strongest cases; fused quotes, brackets, escapes, colons,
semicolons and sentence punctuation have smaller class-specific values.
Ordinary words and single punctuation marks get zero.

A short text tail identifies word-internal 'or' and HTML entities. The
previous token distinguishes dense comma lists and some sentence starts;
the document-end response grows with document position. All state resets
at document boundaries. Values approximate training class means, not the
many small, token-specific background fluctuations.
"""
import re

READS = ()

# Disjunction words: English, French, German, Russian, Chinese, Arabic,
# Scandinavian, Vietnamese, Japanese and Korean, plus 'alternatively'.
ALTERNATIVES = {
    ' or': 1.09, ' Or': 0.92, 'Or': 0.92, ' OR': 0.80,
    ' nor': 0.42, ' Nor': 0.23,
    ' ou': 0.36, ' oder': 0.50, ' или': 0.67, ' либо': 0.67,
    '或': 0.98, ' 或': 0.98, '或者': 0.85, '或是': 0.85,
    ' أو': 0.68, ' eller': 0.49, ' hoặc': 0.77,
    'または': 0.75, ' 또는': 0.68, ' 혹은': 0.57,
    'Alternatively': 0.52, ' Alternatively': 0.52,
    '_or': 0.98, '/or': 0.58, '-or': 0.97,
}
OPEN = set('([{（“「《')
CLOSE = set(')]}）”」》')
QUOTES = set('\'"`”')
ENTITY = re.compile(r'&(?:#[0-9]+|#x[0-9a-fA-F]+|[A-Za-z]+)$')
SENTENCE_STARTS = {
    'the', 'this', 'that', 'these', 'those', 'a', 'an', 'i', 'he',
    'she', 'it', 'we', 'you', 'they', 'in', 'on', 'at', 'as', 'and',
    'but', 'so', 'then', 'there', 'when', 'if', 'is', 'was', 'for',
}


def response(token, recent, position, previous):
    if token == '<|endoftext|>':
        return 1.19 - 0.69 / (1 + position / 3)
    if token in ALTERNATIVES:
        return ALTERNATIVES[token]
    if token in ('or', 'OR'):
        inside_word = recent and recent[-1].isalpha()
        return 0.18 if inside_word else (0.80 if token == 'or' else 0.67)
    s = token.lstrip(' ')
    # Only fused separators fire: a bare comma or comma-newline does not.
    if '，' in s:
        tail = s.split('，', 1)[1]
        if tail and not tail[0].isspace():
            return 4.28 if tail[0].isalpha() else 3.40
    if ',' in s:
        before, tail = s.split(',', 1)
        if tail and not tail[0].isspace():
            if tail[0].isalpha():
                if len(tail) == 1:
                    return 2.25 if previous.startswith((',', ';')) else 2.98
                if tail in ('None', 'NULL', 'null', 'true', 'false'):
                    return 3.03
                return 3.66
            if tail[0] in QUOTES:
                if tail[0] == '”':
                    return 1.14
                if before.endswith(']'):
                    level = 2.19
                else:
                    level = 1.73 if before else 1.35
                return level + 0.75 * tail.count(',')
            if tail[0] == '\\':
                return 1.12 if s[0] == ',' else 0.25
            if tail[0] in OPEN or tail[0] in CLOSE:
                return 1.72
            return 0.95 if tail[0] == ',' else 2.35
    # Less prominent separators and quotation/sentence boundaries.
    if len(s) < 2 or s[1].isspace():
        return 0.0
    head, tail = s[0], s[1:]
    if head == ':':
        if tail[0] in ':=' or tail.startswith('//'):
            return 0.0
        if tail[0] == '\\':
            return 0.30
        return 0.64 if tail[0] in QUOTES else 1.04
    if head == ';':
        if ENTITY.search(recent):
            return 0.23
        if tail[0].isalpha() or tail[0] in '-+':
            return 1.95
        return 0.74 if tail[0] == '\\' else 0.65
    if head == '—' and tail[0].isalpha():
        return 1.25
    if head in '。，、：！？':
        if tail[0] in OPEN:
            return 1.30 if head == '：' else 1.85
        if tail[0] in CLOSE:
            return 0.65
    if head == '」' and tail[0].isalpha():
        return 1.58
    if head == '.' and tail.isalpha() and tail[0].isupper():
        if tail.lower() in SENTENCE_STARTS:
            return 1.10 if previous.startswith(' ') else 0.70
        if len(tail) == 1:
            after_word = previous.startswith(' ') and len(previous.strip()) > 1
            return 0.38 if after_word else 0.13
        return 0.16
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, position, previous = '', 0, ''
    else:
        _, recent, position, previous = carry
    token = prefix.token_strings[-1]
    value = response(token, recent, position, previous)
    return (doc, (recent + token)[-60:], position + 1, token), float(value)

programs.luna:
"""Recognize the frequent English alternative word and an explicit document ending."""
READS = ()
END_MARKER = "<|endoftext|>"

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token == END_MARKER:
        return None, 1.2
    if token.casefold() == "or":
        return None, 1.15
    return None, 0.0

programs.sol:
"""A lexical feature centered on 本 and English 'this' and 'capital'.

本 means root, book, principal/capital, or 'this' in different compounds.
The separate character has the strongest negative response; compounds,
Korean 본, and Japanese この are weaker. 'This' is stronger than 'this',
especially at a document start. 'Like this' largely suppresses the response.
This is a spelling-based approximation, not a general semantic classifier.
"""
READS = ()


def lexical_response(word):
    if word == '一本':                    # One book / one long object.
        return -5.3
    if word in {'资本', '資本'}:          # Capital.
        return -4.0
    if word in {'成本', '本钱', '本錢', '本金'}:  # Cost / principal.
        return -3.5
    if word in {'根本', '本书', '本公司'}:  # Root / this book / this company.
        return -2.8
    if word in {'原本', '本来', '本來', '样本', '樣本', '文本'}:
        return -2.2                       # Original / sample / text.
    if word == '本当に':                  # Japanese 'really', an exception.
        return 0.13
    if word in {'本人', '本身', '本土', '本田', '本当'}:
        return -1.0
    if word in {'本地', '版本', '本周', '本月', '本网'}:
        return -1.4                       # Local / version / this week/month.
    if word == '日本':                    # Japan.
        return -1.8
    if word in {'基本上', '基本面', '本质'}:
        return -0.55                      # Basically / fundamentals / essence.
    if '本' in word:
        return -1.6 if len(word) == 2 else -0.85
    if word == '木':                      # Tree; the character underlying 本.
        return -1.05
    if word == 'この':
        return -1.16                      # Japanese 'this'.
    if word in {'これ', 'questo', 'dieses'}:
        return -0.55                      # Japanese / Italian / German 'this'.
    if word in {'该', '該'}:
        return -0.78                      # The mentioned / this.
    if word == '此':
        return -0.38
    if word == 'these':
        return 0.22
    if word == '这些':
        return 0.32
    if word.lower() in {'japan', 'japanese'}:
        return -0.84
    if word.lower() == 'costs':
        return -0.58
    if word.lower() == 'cost':
        return -0.20
    if word.lower() in {'capitals', 'capitalism', 'capitalist', 'capitalized'}:
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    word, prev = token.strip(), previous.strip()
    bare = word.lstrip('("\'“>,.=:$_-[')
    value = lexical_response(word)

    if bare.lower() == 'this':
        if bare == 'THIS':
            value = -1.25
        elif bare == 'This':
            value = -1.38 if token.startswith(' ') else -1.58
            if start:
                value = -2.07 if token.startswith(' ') else -2.65
            elif token.startswith(('"', '“')):
                value = -1.28
            elif prev in {'*', '//', '/*', '#'}:
                value = -1.65
        else:
            value = -0.88 if token.startswith(' ') else -1.03
            if '\t' in token or token.startswith(('$', '.', '_', '-')):
                value = -1.28
            elif token.startswith(('(', '[')):
                value = -0.88
            elif prev.lower() == 'like':
                value = -0.09
            elif prev.lower() in {'do', 'doing', 'done'}:
                value = -0.38
            elif prev.lower() in {'make', 'making', 'all', 'how', 'think'}:
                value = -0.47
            elif previous.isspace():
                value = -1.08
    elif word == '本':
        # Full decoding handles the preceding character's split UTF-8 bytes.
        preceding = '' if start else prefix.text_prefixes[-1][:-1][-1:]
        value = -7.7
        if preceding in {'日', '脚', '版', '基'}:
            value = -2.5                  # Japan / script / version / basic.
        elif preceding.isdigit():
            value = -6.8                  # Japanese object counter.
        elif preceding in {'資', '资', '书', '書', '絵'}:
            value = -6.3                  # Capital / book compounds.
    elif word == '본':
        value = -3.3 if prev.endswith('원') else -4.4
    elif word.lower() == 'capital':
        value = -2.26 if word == 'capital' else -1.91
        if prev.lower() in {'working', 'venture'}:
            value = -1.65
    return (doc, token), value

programs.luna:
"""Predict negative pulses on English “this”, a particularly common strong trigger."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token == "this":
        return None, -0.9
    if token == "This":
        return None, -1.5
    return None, 0.0

"""Approximate a code-sensitive component by spotting source-code names.

It gives positive scores to dotted members and mixed-case identifiers, especially
near familiar declaration/import words or programming punctuation. It deliberately
ignores ordinary tokens that do not look like part of a code expression.
"""

READS = ()

_CODE_WORDS = (
    "import", "class", "def", "function", "public", "private", "return",
    "const", "var", "new", "void", "using", "throw", "async", "await",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    start = len(prefix.token_strings) - 1
    doc = prefix.document_ids[-1]
    recent = []
    for i in range(start, max(-1, start - 12), -1):
        if prefix.document_ids[i] != doc:
            break
        recent.append(prefix.token_strings[i])
    context = "".join(reversed(recent)).lower()

    code_context = any(word in context for word in _CODE_WORDS)
    code_context |= any(
        mark in context for mark in ("{", "}", ";", "=>", " =", "->", "::", "(")
    )

    letters = [c for c in token if c.isascii() and c.isalpha()]
    mixed_case = any(c.isupper() for c in letters[1:]) and any(
        c.islower() for c in letters
    )
    dotted_member = token.startswith(".") and len(token) > 1 and token[1].isalpha()
    if dotted_member:
        if any(c.isupper() for c in token[1:]):
            value = 0.09 if code_context else 0.02
        else:
            value = 0.05 if code_context else 0.01
    elif mixed_case:
        value = 0.075 if code_context else 0.0
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""English instantiation/complement detector with a few lexical side responses.

The main response is on 'of' after 'instance(s)'. Other example and
representation nouns give smaller positives; quality/dependence nouns give
negatives. Also recognize combinatorial nouns, even split across tokens,
comparison/validity words, and the Chinese word for manifestation/performance.
Remember the last token or completed noun spelling; reset at document boundaries.
Response levels summarize random training examples, not semantic certainty.
"""
READS = ()

EXAMPLES = {
    'example', 'case', 'occurrence', 'appearance', 'illustration', 'impression',
}
REPRESENTATIONS = {
    'definition', 'representation', 'implementation', 'combination',
    'arrangement', 'orientation', 'interpretation',
}
SPECIFICATIONS = {
    'version', 'description', 'position', 'copy', 'distribution', 'state',
}
DEPENDENCE = {
    'dependence', 'relevance', 'sensitivity', 'effectiveness', 'usefulness',
    'correlation', 'comparison', 'validity', 'stability', 'validation',
}
QUALITY = {
    'risk', 'quality', 'influence', 'effect', 'ability', 'control', 'impact',
}
DESCRIPTIVE_NOUNS = REPRESENTATIONS - {'definition', 'combination'}


def singular(word):
    if word == 'copies':
        return 'copy'
    return word[:-1] if len(word) > 3 and word.endswith('s') else word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    split = False
    if ((previous == 'per' and word in {'mutation', 'mutations'})
            or (previous == 'com' and word in {'bination', 'binations'})
            or (previous == 'inst' and word == 'antiation')):
        word = previous + word
        split = True
    base = singular(word)
    value = 0.0
    if base == 'combination':
        value = 0.40 if split else (0.34 if word.endswith('s') else 0.22)
    elif base == 'permutation':
        value = (0.35 if word.endswith('s') else 0.48) if split else 0.28
    elif base in DESCRIPTIVE_NOUNS:
        value = 0.14
    elif base in DEPENDENCE or word in {'compar', 'comparative'}:
        value = -0.41 if reset else -0.13
    elif word in {'表现', '表現'}:
        value = 0.20
    if token == ' of':
        before = singular(previous)
        if before == 'instance':
            value = 0.87 if previous.endswith('s') else 0.99
        elif previous == 'occurrences':
            value = 0.80
        elif before in {'permutation', 'instantiation'}:
            value = 0.62
        elif before in EXAMPLES:
            value = 0.41
        elif before in REPRESENTATIONS:
            value = 0.40
        elif before in SPECIFICATIONS:
            value = 0.28
        elif before in DEPENDENCE:
            value = -0.44
        elif before in QUALITY or previous.endswith('ability'):
            value = -0.22
    return (doc, word), value

programs.luna:
'''Recognize the recurring encyclopedia relation phrase at its final word.'''
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, suffix = carry if carry is not None else (doc, "")
    if doc != old_doc:
        suffix = ""

    text = (suffix + prefix.token_strings[-1]).lower()
    if text.endswith("instance of") or text.endswith("instances of"):
        value = 0.96
    else:
        value = 0.0
    return (doc, text[-40:]), value

programs.sol:
"""A token-form detector centered on loss and absence, not sentence meaning.

English loss inflections and the loss character 失 have strong negative
responses; missing, lacking, and without are weaker. Written fragments and
common loss compounds have different strengths. One-token memory recognizes
loss-of and suffix continuations and resets at document boundaries. For a
split UTF-8 character, decoded text identifies a newly completed 失.
Unrecognized tokens receive zero; 'of' has a small default response.
"""
READS = ()

LOSS = {
    'loss': -3.8, 'lost': -5.0, 'lose': -4.6,
    'losing': -4.7, 'loses': -4.6, 'losses': -2.65,
}
ABSENCE = {
    'missing': -1.65, 'lack': -1.43, 'lacking': -1.75,
    'lacks': -1.7, 'lacked': -1.8, 'without': -0.97,
    'miss': -0.65, 'missed': -0.82, 'misses': -0.7,
    'absence': -0.25, 'absent': -0.3, 'devoid': -0.85,
    'misplaced': -2.3, 'loose': -1.3,
}
OF_PHRASES = {
    'loss': -6.1, 'losses': -3.2, 'lost': -4.7,
    'lack': -1.55, 'absence': -0.62, 'removal': -0.95,
    'deletion': -1.7, 'depletion': -1.0, 'disappearance': -1.4,
    'retention': -1.05, 'gain': -1.1, 'fall': -0.75,
    'destruction': -0.75, 'preservation': -0.85,
    'restoration': -1.1, 'theft': -1.3, 'deprived': -0.95,
    'failure': -0.58, 'out': -0.33, 'end': -0.23,
}
CJK_LOSS = {
    '失': -8.9, '失去': -7.8, '失去了': -6.7, '不失': -7.5,
    '迷失': -5.3, '丢失': -5.9, '流失': -4.3, '丧失': -4.5,
    '损失': -3.6, '損失': -3.6, '失落': -3.25, '缺失': -3.55,
    '丢': -3.4, '丟': -3.4, '丧': -3.7, '喪': -3.1, '丢了': -4.0,
    '缺乏': -2.23, '缺少': -2.2, '失踪': -2.05, '失控': -2.5,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    form = token.strip().lstrip('_.(-')
    word = form.lower()
    spaced = token[:1].isspace()
    value = 0.0
    if word in LOSS:
        value = LOSS[word]
        if not spaced:
            value = {'loss': -2.7, 'lost': -3.9, 'lose': -1.2,
                     'losing': -1.45, 'loses': -0.45}.get(word, -2.0)
        if word == 'loss' and spaced:
            if previous == 'weight':
                value = -2.27
            elif previous == 'fat':
                value = -2.6
            elif previous in {'hearing', 'vision', 'bone'}:
                value = -4.6
            elif previous in {'blood', 'data'}:
                value = -5.1
        if form == 'Lose' and spaced:
            value = -3.0
    elif word in ABSENCE:
        value = ABSENCE[word]
    elif token in CJK_LOSS:
        value = CJK_LOSS[token]
    elif '\ufffd' in token and carry is not None and carry[0] == doc:
        if prefix.text_prefixes[-1].endswith('失'):
            value = -8.2
    if word == 'of':
        value = OF_PHRASES.get(previous, -0.4 if token == '-of' else 0.02)
    elif word in {'es', 'ing'} and previous == 'loss':
        value = -2.4
    return (doc, word), float(value)

programs.haiku:
"""Candidate 5: graded lexicon of loss / lack / absence / removal words.

The component is a 'loss and absence' detector. It goes negative on words for losing
something (strongest), for being without something, and more weakly on gaining, keeping,
removing or deleting things. It also fires on the 'of' that follows such a word
("loss of", "lack of", "removal of"). Values are typical activations per word."""
READS = ()

LOSE = {
    "失": -8.5, "失去": -8.0, "失去了": -7.0, "不失": -7.0, "丢失": -5.5, "迷失": -5.3,
    "流失": -4.7, "损失": -3.5, "丢": -3.5, "丟": -3.4, "丧": -3.3, "失落": -3.2, "缺失": -3.6,
    "lost": -5.0, "losing": -4.1, "lose": -3.7, "loss": -3.4, "losses": -2.7, "loses": -1.5,
    "mất": -3.8, "pérdida": -3.7, "perder": -2.5, "потеря": -2.4,
}
LACK = {
    "missing": -1.6, "_missing": -1.6, "lacking": -1.8, "lacks": -1.8, "lacked": -1.8,
    "lack": -1.4, "缺乏": -2.0, "缺": -1.1, "without": -1.0, "sans": -0.7, "ohne": -0.6,
    "без": -0.55, "无": -0.4, "misplaced": -2.4, "absence": -0.3, "absent": -0.3,
    "devoid": -0.8, "deprived": -0.6, "depletion": -0.4, "disappeared": -0.6, "gone": -0.35,
}
MILD = {
    "gain": -1.1, "gains": -0.9, "gained": -1.1, "gaining": -1.1, "regained": -1.9,
    "retain": -0.8, "retains": -1.2, "retained": -0.6, "won": -0.55, "winning": -0.8,
    "miss": -0.5, "missed": -0.8, "错过": -1.0, "forget": -0.6, "remove": -0.35,
    "removed": -0.4, "deleted": -0.6, "deletion": -0.8, "destroyed": -0.8, "stolen": -0.7,
    "stealing": -0.7, "restore": -0.5, "掉": -0.6, "夺": -1.3, "脱": -1.3,
}
# 'of' right after a loss word gets the loss value; after a lack word, a lack value;
# after other removal/absence nouns, a mild value.
OF_AFTER_LOSS = {"loss": -6.0, "losses": -3.2}
OF_AFTER_LACK = {"lack": -1.5}
OF_AFTER_REMOVAL = {
    "absence", "deprivation", "depletion", "removal", "destruction", "disruption",
    "acquisition", "retention", "deletion", "elimination", "devoid", "deprived", "fall",
}


def step(carry, prefix, upstream):
    w = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if w == "of":
        if prev in OF_AFTER_LOSS:
            return None, OF_AFTER_LOSS[prev]
        if prev in OF_AFTER_LACK:
            return None, OF_AFTER_LACK[prev]
        if prev in OF_AFTER_REMOVAL:
            return None, -0.7
    for table in (LOSE, LACK, MILD):
        if w in table:
            return None, table[w]
    return None, 0.0

