_WORD = re.compile(r"[^\W_]+(?:['’][^\W_]+)*", re.UNICODE)


def step(carry, prefix, upstream):
    """Recognize a few familiar ways to describe loss, absence, or removal."""
    doc = prefix.document_ids[-1]
    previous = ""
