        previous = carry[1]

    raw = prefix.token_strings[-1].casefold()
    # Join a word split across adjacent tokens, but not across a visible space.
    joined = raw if raw[:1].isspace() or not raw[:1].isalpha() else previous + raw
    words = _WORD.findall(joined)
    word = words[-1] if words else ""
    score = 0.0

    if word in _LOSS:
        score = _LOSS[word]
    elif word in _MISSING:
        score = _MISSING[word]
    elif word in _WITHOUT:
        score = _WITHOUT[word]
    elif word in _REMOVAL:
        score = _REMOVAL[word]
    elif word in _KEEP_OR_GAIN:
        score = _KEEP_OR_GAIN[word]
    elif word in _OUTCOME:
        score = _OUTCOME[word]
    elif word == "former":
        score = 0.25
    elif word == "of" and previous in {"loss", "losses", "lose", "lost"}:
        score = -3.0
    elif word == "of" and previous in {"lack", "lacking", "lacks"}:
        score = -1.6
    elif word == "of" and previous in {"absence", "shortage", "deficit"}:
        score = -0.7

    # These characters often make up loss/lack words in Chinese and Japanese.
    if any(ch in raw for ch in "失损損丢"):
        score = min(score, -4.5)
    elif any(ch in raw for ch in "無无缺漏"):
        score = min(score, -0.8)

    carry_word = word if raw and raw[-1:].isalpha() else ""
    return (doc, carry_word), float(score)

"""A small spelling-fragment cue for this component's positive response.

Short adjacent letter-only tokens suggest a word split across pieces.
A two-letter token at a word start followed by another short piece gets
an extra bump, as do Katakana-to-Katakana pieces. This is a rough cue,
not a word or name lookup.
