def step(carry, prefix, upstream):
    i = prefix.position
    token = prefix.token_strings[i]
    if i > 0 and prefix.document_ids[i] == prefix.document_ids[i - 1]:
        previous = prefix.token_strings[i - 1].lstrip()
        if (
            _katakana(token)
            and _katakana(previous)
        ):
            return None, 0.30
        if (
            token.isalpha()
            and previous.isalpha()
            and len(token) <= 3
            and len(previous) <= 3
        ):
            if (
                prefix.token_strings[i - 1][:1].isspace()
                and len(previous) == 2
                and len(token) >= 2
            ):
                return None, 0.12
            return None, 0.04
    return None, 0.0


def _katakana(text):
    return bool(text) and all("\u30a0" <= char <= "\u30ff" for char in text)

programs.sol:
"""A token-boundary-sensitive detector of written-out escape spellings.

Backslash plus a letter in one token responds strongly, especially n/t.
Hexadecimal byte and Unicode escape prefixes also respond. Splitting the
backslash and letter across tokens weakens the response; repeated escapes
and number neighbors adjust it. Longer backslash-led names respond less.
Double underscores and @/&/%-prefixed words have smaller responses.

These are fitted spelling-based approximations, not a whitespace parser:
real newlines/tabs are near zero. Only the previous token is remembered,
and it is forgotten at each document boundary.
"""
READS = ()
HEX_DIGITS = frozenset('0123456789abcdefABCDEF')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token.startswith('\\x') and all(c in HEX_DIGITS for c in token[2:]):
        value = 2.35 if token[2:3] in ('a', 'b', 'e') else 3.3
        if previous == '\\n':
            value -= 1.0
    elif token.startswith('\\u') and all(c in HEX_DIGITS for c in token[2:]):
        value = 3.65
    elif token.startswith('\\') and token[1:].isascii() and token[1:].isalpha():
        name = token[1:]
        if name == 'n':
            value = 5.4
            if previous == '\\n':
                value = 4.15
            elif previous == 'n':
                value = 4.45
            elif previous.strip().isdigit():
                value = 4.9
            elif previous == '\\t':
                value = 4.8
            elif not previous:
                value = 4.52
        elif name == 't':
            value = 4.05 if previous == '\\n' else 4.53
            if not previous or previous.strip().isdigit():
                value = 6.2
        elif len(name) == 1:
            value = 4.4
        else:
            value = max(0.3, 3.0 - 0.22 * len(name))
    elif previous.endswith('\\') and token.isascii() and token.isalpha():
        if token in ('n', 't', 'r', 'u', 'x'):
            value = 1.7 if token == 'n' else 1.5
            if previous.endswith('\\\\'):
                value -= 0.58
        elif token.startswith('n'):
            value = 0.8
    elif token == 'n':
        value = -0.08
    elif token.strip() == '__':
        value = 0.36
    elif len(token) > 1 and token[1:].isascii() and token[1:].isalpha():
        if token[0] == '@':
            value = 1.4
        elif token[0] == '&':
            value = 0.8
        elif token[0] == '%':
            value = 1.5
    return (doc, token), float(value)

programs.luna:
"""Approximate a response to written backslash escapes in code and text.

The largest responses are to the literal ``\\n`` and ``\\t`` tokens,
then to hexadecimal escapes. A split ``\\`` + ``n`` is a smaller cue.
"""

READS = ()

def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = ""
    if carry is not None and carry[0] == document:
        previous = carry[1]

    if token == "\\n":
        value = 4.85
    elif token == "\\t":
        value = 4.6
    elif token == "\\r":
        value = 4.2
    elif token == "\\x":
        value = 3.1
    elif token.startswith("\\x"):
        value = 2.3
    elif token == "n" and previous.endswith("\\"):
        value = 1.65
    else:
        value = 0.0

    return (document, token), value

programs.sol:
"""A lexical signal for novelty, invention, and transformative change.

Revolution and innovation are strongest. Reform, invention, novelty, and
established conventions are weaker. Creative language is weaker still.
The code recognizes East Asian equivalents and follows split Latin words;
it does not decide from context whether an idea is genuinely new.
"""

READS = ()

# Translations of revolution, innovation, reform, tradition, and creation.
# The Korean syllable 혁 occurs in innovation and revolution words.
TRANSLATIONS = {
    '革命': -5.8, '创新': -4.7, '創新': -3.8, '革新': -3.8,
    '改革': -3.2, '变革': -2.6, '變革': -2.6, '혁': -3.1,
    '创': -1.9, '創': -1.2, '革': -4.7,
    '创业': -2.1, '創業': -1.8, '科技创新': -1.8,
    '传统': -1.5, '傳統': -1.2, '传统的': -1.25,
    '创意': -1.1, '新颖': -1.0, '改进': -0.85,
    '突破': -0.75, '转型': -0.75, '改造': -0.75,
}


def lexical_signal(token):
    word = token.strip(' \t\r\n._-').lower()
    if word in TRANSLATIONS:
        return TRANSLATIONS[word]
    if '创新' in word or '創新' in word:
        return -2.1
    if word == 'revolution':
        return -4.9
    if word.startswith('revolution'):
        return -3.7
    if word == 'innovation':
        return -3.6
    if word == 'innovative':
        return -3.35 if token.strip().islower() else -2.8
    if word.startswith('innovat') or word == 'innov':
        return -2.9
    if word == 'novel':
        return -1.5 if token.strip().islower() else -1.1
    if word.startswith('novel'):
        return -0.9
    if word == 'nov':
        if token.strip() != 'nov':
            return -0.85
        return -0.45 if token.startswith(' ') else -1.5
    if word == 'rev':
        if token.strip() == 'Rev' and not token.startswith(' '):
            return -2.0
        return -1.6 if token.startswith(' ') else -0.9
    if word.startswith('reform'):
        return -1.65
    if word.startswith(('traditional', 'conventional', 'unconventional')):
        return -1.1
    if word.startswith('invention') or word in {
        'inventor', 'inventors', 'invented'
    }:
        return -1.0
    if word.startswith(('renovat', 'pioneer', 'evolution')) or word == 'renov':
        return -1.1
    if word in {
        'transformative', 'inventive', 'groundbreaking', 'entrepreneurship'
    }:
        return -1.5
    if word == 'transformation':
        return -1.0
    if word.startswith(('transform', 'creativ', 'imaginat', 'evolv')):
        return -0.65
    if word.startswith(('rebel', 'revolt', 'reviv', 'entrepreneur', 'revision')):
        return -0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    tail = token.lower()
    value = lexical_signal(token)

    # These endings convey the theme only when their stem precedes them.
    if token.isascii() and token.isalpha():
        if previous.endswith('nov') and tail in {'el', 'els'}:
            value = -1.2 if tail == 'el' else -0.85
        elif previous.endswith('innov') and tail in {
            'ation', 'ations', 'ative', 'ator', 'ators', 'ate', 'ating'
        }:
            value = -2.7
        elif previous.endswith('rev') and tail in {'olution', 'olutions'}:
            value = -4.3 if tail == 'olution' else -2.8
        elif previous.endswith('ev') and tail in {'olution', 'olutions'}:
            value = -1.3
        elif previous.endswith('inn') and tail == 'ovation':
            value = -2.2
        elif previous.endswith('con') and tail == 'ventional':
            value = -1.25
        elif previous.endswith('in') and tail in {'nov', 'novation'}:
            value = -3.1
        whole = (previous + tail)[-24:]
    else:
        whole = token.strip().lower()
    return (doc, whole), float(value)

programs.haiku:
"""Layer-0 MLP component 3148: a detector for Python names and literals.

What it responds to, in plain terms:
- the type name `str` most strongly (`x = str(n)`, `-> str`, `: str`);
- literal constants `None`, `True`, `False`, and `null`, `true`, `false`, `NULL`;
- common library and typing names (`os`, `datetime`, `pd`, `Optional`, ...);
- other Python built-in names (`len`, `print`, `bool`, `isinstance`, ...), weakly;
- `self`, moderately;
- opening brackets and braces of code and JSON (`[`, ` {"`), weakly;
- the f-string opener `(f`, fairly strongly.

A name glued to punctuation (`(len`, `=True`, `[str`) counts as the name.
It is strongest when the name sits in code, right after an operator, bracket,
quote, comma or colon, or after `in`, `is`, `return`. The same word in ordinary
prose ("the list") is weak. Every other token, including ordinary words and
most punctuation, predicts 0.

The values are rough conditional means fitted on training text. The program is a
word-class lookup times a code-or-prose factor from the previous token; it is not a
table of token ids.
"""

import builtins
import re

READS = ()

BUILTIN_NAMES = {name for name in dir(builtins) if not name.startswith("_")}
LITERALS = {"None", "True", "False", "null", "NULL", "true", "false"}
LIBRARY_NAMES = {
    "os", "sys", "re", "json", "datetime", "requests", "pd", "np", "typing",
    "pytest", "inspect", "logging", "subprocess", "argparse", "hashlib",
    "collections", "Optional", "List", "Dict", "Any", "Type", "Union",
}
OPENERS = {"[", " [", "{", " {", '{"', ' {"'}

# activation per word class: (after a code-like token, after prose)
VALUE = {
    "str": (2.2, 1.0),
    "literal": (1.0, 0.8),
    "library": (0.7, 0.15),
    "builtin": (0.5, 0.1),
    "self": (0.5, 0.2),
    "opener": (0.35, 0.15),
    "fstring": (0.8, 0.8),
}


def word_class(token):
    """Class of a token: its word with leading punctuation removed, or an opener."""
    if token == "(f":
        return "fstring"
    if token in OPENERS:
        return "opener"
    word = re.sub(r"^[^A-Za-z]+", "", token)
    if word == "str":
        return "str"
    if word in LITERALS:
        return "literal"
    if word in LIBRARY_NAMES:
        return "library"
    if word in BUILTIN_NAMES:
        return "builtin"
    if word == "self":
        return "self"
    return None


def after_code(previous):
    """True if the previous token is punctuation/operator-like or an in/is/return keyword."""
    if not previous:
        return False
    return not re.search("[A-Za-z]", previous) or previous in ("in", "is", "return")


def step(carry, prefix, upstream):
    cls = word_class(prefix.token_strings[-1])
    if cls is None:
        return None, 0.0
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip()
    column = 0 if after_code(previous) else 1
    return None, float(VALUE[cls][column])

programs.luna:
"""Recognize familiar Python names near punctuation used in source code."""

READS = ()

BUILTINS = {
    "bool", "dict", "float", "int", "len", "list", "object", "range",
    "str", "tuple", "type", "input", "print", "open", "enumerate",
    "zip", "set", "map", "filter", "super", "isinstance",
}
VALUES = {"none", "true", "false", "null", "self"}
MODULES = {"json", "os", "sys", "datetime", "math", "pathlib"}
CODE_MARKS = ("=", ":", "(", ".", "[", "{", "\n")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    words, part = set(), ""
    for char in token:
        if char.isalnum() or char == "_":
            part += char
        elif part:
            words.add(part)
            part = ""
    if part:
        words.add(part)
    if not words & (BUILTINS | VALUES | MODULES):
        return None, 0.0

    recent = prefix.token_strings[-12:]
    documents = prefix.document_ids[-12:]
    cut = 0
    for i in range(len(documents) - 1, -1, -1):
        if documents[i] != documents[-1]:
            cut = i + 1
            break
    before = "".join(recent[cut:-1]).lower()
    if any(mark in before for mark in CODE_MARKS):
        return None, 0.5
    return None, 0.0

