"""Approximate the component's negative response to letter chunks containing gn.

Short roots (especially ign, agn, align) are usually strongest. Completed
words have weaker, family-dependent responses: sign and ignore are stronger
than design, signal, or foreign. Constants summarize training measurements.
Activity can persist into an attached suffix or the next of/with. This short
memory resets with each document. Smaller non-gn and positive responses are
not modeled; no token IDs or model internals are used.
"""
READS = ()


def lexical(token):
    word = token.strip().strip('._-').lower()
    if 'gn' not in word:
        return 0.0
    if 'design' in word or word.startswith(
            ('signal', 'foreign', 'campaign', 'champagn')):
        return 0.0
    if word in {'ign', 'agn', 'aign'}:
        return -5.3 if word == 'ign' else -4.75
    if word.startswith('align'):
        if word == 'align':
            return -4.6
        if word == 'aligned':
            return -3.8 if token[:1].isspace() else -1.65
        return -3.15
    if word == 'sign':
        return -1.4 if token[:1].isspace() else -1.8
    if word.startswith(('sign', 'assign', 'unsigned')):
        if word in {'signs', 'signed', 'signing', 'assign', 'unsigned'}:
            return -0.8
        return -0.3
    if word.startswith(('ignit', 'ignoran')):
        return -2.2
    if word.startswith('ignor'):
        return -1.8 if word == 'ignore' else -1.3
    if word.startswith(('diagnos', 'prognos')):
        return -1.8 if word.endswith(('sis', 'se')) else -1.2
    if word.startswith('magnitud'):
        return -1.9
    if word.startswith('malignan'):
        return -1.4
    if word.startswith(('recogn', 'cognit')):
        return -0.65
    if word.startswith(('pregn', 'magnet')):
        return -0.2
    if word in {'reign', 'resigned'}:
        return -2.0
    if word.endswith('sign'):
        return -1.1
    if word.endswith('egn'):
        return -1.3
    if word.endswith('gn'):
        if word == 'gn':
            return -1.1 if token.strip()[0].isupper() else -2.7
        if word in {'cogn', 'lign', 'ogn'}:
            return -2.7
        short_root = len(word) <= 5 or word in {'benign', 'malign', 'progn'}
        return -3.6 if short_root else -0.5
    # Short gn-bearing inflectional fragments, not initial gnu/gni chunks.
    ending = word.split('gn', 1)[1]
    if word.startswith(('ign', 'aign')) and ending in {'ed', 'er', 'ant', 'ment'}:
        return -2.8
    if len(word) <= 5:
        if ending in {'a', 'ed'}:
            return -2.9
        if ending in {'e', 'er'}:
            return -2.3
    return -0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, previous, strength = carry
    token = prefix.token_strings[-1]
    word = token.strip().strip('._-').lower()
    value = lexical(token)
    # Continue a strong root into a suffix or linking preposition.
    if value == 0.0 and strength < -1.0:
        if token.isalpha() and token[:1].islower():
            ratio = 0.15
            if previous == 'align' and token in {'s', 'ing'}:
                ratio = 0.72
            elif previous == 'magn' and token == 'ification':
                ratio = 0.45
            elif previous.endswith('gn') and token == 's':
                ratio = 0.4
            value = ratio * strength
        elif token in {' of', ' with'}:
            value = strength * (0.34 if token == ' of' else 0.2)
    return (doc, word, value), float(value)

"""Approximate the document-end response and weaker lowercase-l responses.

The strongest training responses are negative at the document-end marker.
Chat markers receive much smaller fixed values. Isolated l and short
capital/l, punctuation/l, or two-consonant l fragments receive negative
values; capital I followed by l is treated as a vertical-stroke fragment.
For isolated l, the preceding token's case and function-word class adjust
its strength. Romance function words suggest an elided article rather than
an isolated letter, so that response is suppressed. Other tokens get zero.
