import string

READS = ()

MARKERS = {
    '<|endoftext|>': -1.336,
    '<|im_start|>': -0.025,
    '<|im_end|>': -0.029,
    '<tool_response>': 0.085,
    '<think>': -0.079,
    '</think>': -0.016,
}
ROMANCE_FUNCTION_WORDS = set(
    'de à pour dans que e a con en da di per del la et un une '
    'sur les le des qui du au avec'.split()
)
ENGLISH_FUNCTION_WORDS = set(
    'the and of to for with from on in is a an or'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    text = token.strip()
    value = MARKERS.get(token, 0.0)
    if token == '<|endoftext|>' and not previous:
        value = -0.938
    elif text == 'l':
        if token[0].isspace():
            word = previous.strip().lower()
            if word in ROMANCE_FUNCTION_WORDS:
                value = 0.005
            elif word in ENGLISH_FUNCTION_WORDS:
                value = -0.46
            else:
                value = -0.195 if previous[-1:].islower() else -0.28
        elif previous[-1:].islower():
            value = -0.15
        elif previous[-1:].isupper():
            value = -0.71
        else:
            value = -0.48
    elif 2 <= len(text) <= 3 and text[0] == 'I' and set(text[1:]) == {'l'}:
        value = -0.36
    elif len(text) == 2:
        first, last = text
        if last == 'l' and first in string.ascii_uppercase:
            value = -0.235
        elif last == 'l' and first in string.punctuation:
            value = -0.45 if first in '-/' else -0.27
        elif first == 'l' and last in string.ascii_lowercase:
            if last not in 'aeiouy':
                value = -0.16
    return (doc, token), value

