"""Conversation markers and separated East Asian characters.

Large positive values identify turn, tool, and thinking delimiters. Document
starts are weaker; turn endings depend on the preceding ending. Smaller values
identify single Han, kana, or Hangul characters after separate separators or
numbers, not characters inside continuous text. Leading-space tokens and
multi-character tokens respond less, as do Han pronouns and conjunctions.
Other text is approximated by a near-zero baseline.
"""
import unicodedata

READS = ()
MARKERS = {
    '<think>': 2.04, '</think>': 0.80,
    '<tool_call>': 1.46, '</tool_call>': 2.92,
    '<tool_response>': 2.47, '</tool_response>': 3.38,
    '<|endoftext|>': 0.02,
}
HAN_PRONOUNS = frozenset('我你他她它您咱俺谁誰这這那哪其此')
HAN_CONJUNCTIONS = frozenset('和与與及或但而虽雖且')
SEPARATION = {
    'space': 0.70, 'number': 0.53, 'opening': 0.77,
    'comma': 0.35, 'punctuation': 0.52, 'other': 0.30,
    'start': 0.02,
}


def script(c):
    if '\u4e00' <= c <= '\u9fff':
        return 'Han'
    if '\u3040' <= c <= '\u30ff' and c not in '・ー':
        return 'kana'
    if '\uac00' <= c <= '\ud7af':
        return 'Hangul'
    return ''


def preceding_kind(text):
    if not text:
        return 'other'
    c = text[-1]
    if c.isspace():
        return 'space'
    if c.isdigit():
        return 'number'
    category = unicodedata.category(c)
    if c == '，':
        return 'comma'
    if category in ('Ps', 'Pi'):
        return 'opening'
    if category.startswith('P'):
        return 'punctuation'
    if script(c) == 'kana':
        return 'kana'
    return 'continuation' if script(c) or c == '\ufffd' else 'other'


