CJK_LANGUAGE = {"语言", "語言", "語", "语", "言", "语言学"}
LANGUAGE_NAMES = {"english", "spanish", "french", "arabic", "chinese", "german"}
RELATED = {"grammar", "syntax", "vocabulary", "terminology", "speak", "speaks",
           "speaking", "spoken", "lexical", "translation"}
LOOKALIKE = {"statement", "statements", "league"}

