"""Connecting words and marked line endings, amplified in literary prose.

This is a partial reconstruction: it recognizes grammatical forms, not a
lookup over arbitrary tokens. A fading count of sensory, archaic, and
narrative cues raises the response; code-like text lowers it. Space before
a blank line and commas joined to newlines are especially salient.
"""
READS = ()
GRAMMAR = set('''a an the and but or nor yet so as when while though where
    that who with upon from of in on to through under against like
    my your his her its our their'''.split())
POSSESSIVES = set('my your his her its our their'.split())
# Small lexical differences among these familiar grammatical forms.
LOWER_BIAS = {
    'but': -.04, 'so': -.05, 'our': -.05, 'her': .09, 'their': .09,
    'upon': .14, 'against': .16, 'through': .07, 'under': .07,
}
LINKS = {
    'thy': .80, 'thou': .37, 'thee': .15, 'ye': .11,
    'und': .16, 'als': .33, 'daß': .50, 'dass': .20,
    'dans': .29, 'où': .54, 'comme': .17, 'wie': .15,
}
CHINESE = {'着': .59, '著': .25, '你': .38, '你的': .42,
           '您': .14, '在': .18}
LITERARY = set('''thy thou thee ye ere hath doth shalt o
    warm bright soft fair sweet cold thick deep dark light heavy gentle
    glad sad pale golden shining tender heart eyes lips arms cheeks breast
    face hand hands head hair neck voice breath love joy sorrow fear grief
    beautiful beauty cried whispered smiled laughed gazed looked felt'''.split())
NARRATIVE = set('''he she his her him himself herself said says asked replied
    whispered shouted cried smiled laughed nodded murmured gazed stared'''.split())
CODE = set('''function class return const var import def int void public
    private type value data model equation matrix theorem proof'''.split())
