RESPONSE = {
    'capital_and': [0.458, 0.388, 0.153, -0.08],
    'capital_article': [-0.012, -0.09, 0.053, -0.009],
    'capital_but': [0.17, 0.168, 0.082, -0.035],
    'capital_link': [0.012, 0.038, 0.109, -0.018],
    'capital_possessive': [0.049, 0.117, 0.112, -0.023],
    'capital_that': [0.1, 0.109, 0.137, -0.047],
    'capital_where': [0.245, 0.081, 0.225, -0.045],
    'comma_blank': [0.493, 0.28, 0.093, -0.032],
    'comma_line': [0.381, 0.349, 0.155, -0.056],
    'contraction': [0.234, 0.223, 0.131, -0.012],
    'grammar': [0.002, -0.002, 0.026, 0.0],
    'possessive': [-0.04, 0.065, 0.067, -0.009],
    'space_blank': [0.298, 0.92, 0.047, -0.032],
    'space_line': [-0.01, 0.16, 0.036, -0.004],
    'where': [0.081, 0.058, 0.111, -0.026],
    'with_like': [0.02, 0.029, 0.092, -0.021],
}


def classify(s):
    w = s.strip()
    low = w.lower()
    if '\n' in s:
        if w in {',', '，'}:
            return ('comma_blank' if s.count('\n') > 1 else 'comma_line'), 0.
        if not w and s.startswith(' '):
            return ('space_blank' if s.count('\n') > 1 else 'space_line'), 0.
        if w == '),' and s.count('\n') > 1:
            return 'comma_blank', -.12
    if s in {"'d", '’d'}:
        return 'contraction', 0.
    if low in GRAMMAR and (w.istitle() or (w.islower() and s.startswith(' '))):
        if w.istitle():
            if low in {'and', 'but', 'where', 'that'}:
                kind = 'capital_' + low
            elif low in {'a', 'an', 'the'}:
                kind = 'capital_article'
            elif low in POSSESSIVES:
                kind = 'capital_possessive'
            else:
                kind = 'capital_link'
            gap = {'and': .15, 'but': .05, 'where': .30, 'that': .28}
            return kind, gap.get(low, .08) * (not s.startswith(' '))
        kind = 'possessive' if low in POSSESSIVES else 'grammar'
        if low in {'with', 'like'}:
            kind = 'with_like'
        if low == 'where':
            kind = 'where'
        return kind, LOWER_BIAS.get(low, 0.)
    return None, 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, literary, code = 0, 0., 0.
    else:
        _, age, literary, code = carry
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    kind, value = classify(s)
    if kind in RESPONSE:
        base, initial, prose, syntax = RESPONSE[kind]
        value += base + initial / (age + 1)**.5
        value += prose * min(literary, 12.) + syntax * min(code, 8.)
    elif s in CHINESE:
        value = CHINESE[s]
    elif s.startswith(' ') and w in LINKS:
        value = LINKS[w]
    elif s == '.':
        value = -.022
    elif s == '!':
        value = -.09
    cue = w in LITERARY or s == ' \n\n'
    literary = literary * (63/64) + cue + .5 * (w in NARRATIVE)
    syntax = w in CODE or any(c in s for c in '{}[]=;_\t') or s.startswith('  ')
    code = code * (15/16) + syntax
    return (doc, age + 1, literary, code), float(value)

