QUIETNESS = {
    'quiet': -5.08, 'quietly': -3.47, 'quieter': -3.09,
    'calm': -2.36, 'calmly': -1.44, 'calming': -0.97,
    'silent': -1.86, 'silence': -1.67, 'silently': -1.36,
    'silenced': -1.05, 'serene': -1.32, 'tranquil': -1.61,
    'tranqu': -1.32,  # beginning of tranquility / tranquil
    'peace': -0.53, 'peaceful': -1.43, 'peacefully': -0.93,
    'solitude': -0.83,
}
SOUND = {
    'noise': -1.31, 'noisy': -1.54, 'noises': -1.02,
    'loud': -0.86, 'loudly': -1.17, 'louder': -0.74,
    'softly': -0.54, 'headphones': -0.71,
}
WAITING = {
    'wait': -0.89, 'waiting': -0.60, 'waited': -0.71,
    'waits': -0.68, 'pause': -0.72, 'pauses': -0.71,
    'paused': -0.44,
}
PRIVACY = {'privacy': -0.65, 'confidentiality': -0.43}

# Chinese characters and words for quietness, calm, silence, static and noise.
CHINESE = {
    '静': -5.18, '靜': -4.75, '安静': -4.81,
    '静静': -4.35, '静静地': -3.67,
    '平静': -2.55, '冷静': -2.64, '宁静': -2.53,
    '寂静': -2.53, '动静': -2.47, '寂': -1.62,
    '安宁': -1.26, '默': -0.78, '默默': -0.72,
    '沉默': -1.06, '静态': -1.52, '静电': -1.01,
