    surface = token.strip().lstrip('-./_(')
    word = surface.lower()
    spaced = bool(token and token[0].isspace())
    value = 0.0
    for cues in (QUIETNESS, SOUND, WAITING, PRIVACY, CHINESE):
        if word in cues:
            value = cues[word]
            break

    if word == 'quiet':
        value = (-5.08 if spaced else -4.18)
        if surface == 'Quiet':
            value = (-4.81 if spaced else -3.75)
    elif surface == 'Silent':
        value = -1.22
    elif word == 'loud' and not spaced:
        value = -0.43
    elif word == 'wait':
        value = -0.92 if spaced else -0.65
        if surface == 'Wait':
            value = -0.885 if spaced else -0.859
    elif word == 'hmm':
        value = -0.36 if spaced else -0.057
    elif word in {'static', 'staticmethod', 'statically'}:
        value = -0.92 if word == 'statically' else -1.08
        if word == 'staticmethod' or token == '.static':
            value = -1.5
        elif token == 'static':
            value = -0.8
        elif token == 'Static':
            value = -1.19
        elif token == ' Static':
