"""Stillness detector: a negative activation on words for quiet and silence (strongest), on
noise and static, and on waiting or pausing; weaker on a few calm or idle words. Otherwise zero.

Each word is lowercased and stripped of leading punctuation, then matched by its start (or,
for the weak list and "wait", exactly), so "quiet", "quietly", "silence", "silenced", "calmly",
"noisy", "static", "statically", "waiting" all fire, and "waiter" does not.
"""
READS = ()

QUIET = ("quiet",)  # the strongest: "quiet", "quietly", "quieter"
CALM = ("silen", "calm", "tranquil", "serene", "hushed")  # silence and calm
NOISE = ("noise", "static", "loud", "buzz")  # noise and static
WAIT = {"wait", "waits", "waiting", "waited", "pause", "paused", "pausing"}  # waiting and pausing
PEACE = ("peace",)  # peace, peaceful
WEAK = {"idle", "busy", "lonely", "awake", "listen", "listening", "whisper", "still", "relax",
        "stop", "await", "awaiting", "patience"}
CJK_QUIET = "静靜"  # quiet and still, in Chinese
CJK_CALM = "寂"  # lonely and still, in Chinese


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lstrip(".-_/").lower()
    if word.startswith(QUIET) or any(c in CJK_QUIET for c in word):
        value = -4.5
    elif word.startswith(CALM) or any(c in CJK_CALM for c in word):
        value = -2.0
    elif word.startswith(NOISE):
        value = -1.3
    elif word in WAIT:
        value = -0.85
    elif word.startswith(PEACE):
        value = -0.7
    elif word in WEAK:
        value = -0.3
