programs.sol:
"""Detect short chunks spelling /ts/, across writing systems.

Negative responses are strongest for TypeScript's .ts suffix, Latin ts/tz,
Cyrillic ц, and Japanese tsu. Longer chunks usually dilute the response.
The preceding character distinguishes isolated ts from a word's ending,
and weakens French circumflex-vowel + ts endings (usually silent).
A separate, smaller positive response covers selected words expressing
exclusivity, separation, or directness. Unrecognized text predicts zero.
This is a spelling heuristic, not a full pronunciation model.
"""
READS = ()

EXCLUSIVE = {'entirely', 'separately', 'devoted', 'purely', 'wholly'}
SPECIFIC = {'instead', 'specifically', 'expressly', 'peculiar'}
DIRECT = {
    'already', 'directly', 'separate', 'dedicated', 'merely',
    'alone', 'altogether', 'exclusively', 'sole',
}
# Present-tense verbs: their final -ts does not behave like an isolated ts.
VERBS = {'gets', 'sets', 'puts', 'hits', 'fits', 'acts'}
TZ_RIMES = {'tz', 'atz', 'itz', 'utz', 'artz', 'ertz', 'antz', 'ritz'}
POSITIVE_WORDS = EXCLUSIVE | SPECIFIC | DIRECT


def spelling_score(token, previous):
    word = token.strip()
    low = word.lower()
    size = len(low)
    leading_space = token[:1].isspace()
    before = previous[-1:] if previous else ''

    if low in {'.ts', '/ts', '-ts'}:
        return -5.15
    if low == 'ts':
        if not word.islower():
            return -3.0
        if leading_space:
            return -3.8
        if before in {'ê', 'û', 'ô'}:
            return -0.85
        return -4.1 if before and not before.isalpha() else -2.55
    if low in {'typescript', 'tslint', '_ts'}:
        return -3.2 if word.islower() else -2.1
    if low in {'tsx', '.tsx'}:
        return -1.0
    if low == '(ts':
        return -2.9

    if low == 'tz':
        return -3.1 if word.islower() else -2.6
    if 'tz' in low:
        if low in TZ_RIMES and not leading_space:
            return -3.7 if low == 'itz' else -2.8
        if low == 'etz' and not leading_space:
            return -1.8
        if low.startswith('itz') and size <= 5:
            return -2.4
        return -1.1 if size <= 4 else -0.5
    if low in {'atsu', 'itsu'}:
        return -4.1 if low == 'atsu' else -1.7
    if 'ts' in low:
        if low == 'its':
            return -0.25 if leading_space else -0.55
        if low in VERBS:
            return 0.0
        if low in {'ats', 'ets', 'uts'}:
            if low == 'ats' and before.isupper() and not leading_space:
                return -2.3
            return -1.45
        if low == 'ots':
            return -0.7
        if size <= 3:
            return -1.2
        if size == 4:
            if word[0].isupper():
                return -1.25
            if low[:2] in {'an', 'en', 'as', 'is'}:
                return -0.2
            return -0.7
        return -0.12 if low.endswith('ts') else 0.0

    if 'ц' in low:
        if size == 1:
            strength = 4.1 if word.islower() else 3.7
            return -strength - (0.35 if leading_space else 0.0)
        if size == 2:
            if low.endswith('ц'):
                return -3.0
            vowel = low[-1]
            return -1.25 if vowel == 'и' else -3.0 if vowel == 'у' else (
                -2.5 if vowel == 'а' else -1.9
            )
        if low in {'ция', 'ции', 'цию', 'ций', 'аци'}:
            return -0.2
        if size == 3:
            return -1.9 if low.endswith(('цев', 'цов', 'цы')) else -0.8
        return -0.15
    if 'ツ' in word:
        return -6.0 if size == 1 else -4.6 if word == 'ッツ' else -0.5
    if 'つ' in word:
        return -2.8 if size == 1 else -0.9 if size == 2 else -0.15
    if word in {'ず', 'づ', '쓰'}:
        return -1.35
    if word in {'ズ', 'ち', 'っ'}:
        return -0.35
    if word in {'チ', 'ッチ', 'ット', 'ț', 'ţ', 'ç'}:
        return -0.6
    if word == '츠':
        return -2.8
    if word == 'تس':
        return -2.4 if leading_space else -3.7
    if 'צ' in word or 'ץ' in word:
        return -2.5 if size == 1 else -0.8 if size == 2 else 0.0
    if low in {'cz', 'sz', 'asz', 'rz'}:
        return -0.8
    if low == 'z':
        return -0.15
    # Chinese characters used for ts-like syllables in transcribed names.
    if word in {'茨', '兹'}:
        return -5.7 if word == '茨' else -2.3
    if word == '津':
        return -1.35
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    low = word.lower()
    value = spelling_score(token, previous)
    if low == 'solely':
        value = 1.45
    elif low in EXCLUSIVE:
        value = 1.0
    elif low in SPECIFIC:
        value = 0.75
    elif low in DIRECT:
        value = 0.5
    if low in POSITIVE_WORDS and not word.islower():
        value *= 0.5
    if word in {'专门', '单纯', '专用', 'だけ'}:
        value = 2.5 if word == '专门' else 1.6 if word == '单纯' else 0.6
    elif word in {'уже', 'сразу', 'специально'}:
        value = 0.55 if word == 'уже' else 0.85
    return (document, token), float(value)

"""Approximate a detector for d-final spelling pieces.

Short pieces ending in d, Cyrillic д, or Arabic د are negative. Latin
consonant clusters and continuation inside a word strengthen the response;
common complete words and grammatical endings weaken it. Plural -s retains
a weaker response. End-of-text is positive; ampersands and alternating
ordinary/nonbreaking spaces have separate negative responses.

Only the preceding token's final character is retained, within a document.
"""
READS = ()

FUNCTION_WORDS = set('and und had did would could should'.split())
IRREGULAR_VERBS = set('''
said read lead led find found hold held told heard paid stood understood
build send spend spread bound sold understand stand
'''.split())
COMMON_WORDS = set('''
good old red bad hard kind hand food blood world word land end need sound
second third hundred thousand around behind beyond toward forward instead
board card ground head mind standard record period solid rapid child
cold gold wood award sand band fund odd dead brand loud proud crowd avoid
'''.split())
CODE_WORDS = set('''
id pid add void command method valid invalid load download password append
thread yield
'''.split())
WHOLE_WORDS = IRREGULAR_VERBS | COMMON_WORDS | CODE_WORDS


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    word = text.strip()
    low = word.lstrip('._/(*-\'’').lower()
    inside = text[:1].isalpha() and previous.isalpha()
    plural = low.endswith('ds')
    if plural:
        low = low[:-1]
    n = len(low)
    value = 0.0
    if word == '<|endoftext|>':
        value = 0.84
    elif text.startswith(' ') and '\u00a0' in text and not word:
        value = -min(1.1, 0.45 * text.count('\u00a0'))
    elif word.endswith('&'):
        value = -0.55 if word.endswith('&&') else -0.67
    elif low.endswith(('ed', 'wood', 'land', 'idad', 'fold')):
        pass
    elif low.endswith('ward') and (n > 4 or word.islower()):
        pass
    elif n >= 4 and low.endswith('id'):
        value = -0.15
    elif low in {'sind', 'wird'}:
        value = -0.25
    elif low in FUNCTION_WORDS:
        value = -0.2 if inside else 0.0
    elif low in WHOLE_WORDS:
        value = -0.5 if inside and n <= 3 else -0.03
        if low == 'id':
            value = -0.75 if inside else 0.0
            if not word.islower():
                value = -0.35
            if not text[:1].isalpha():
                value = 0.18 if word.startswith('_') else 0.0
    elif low.endswith('d'):
        value = -0.6 - 0.2 * inside
        if n >= 5:
            value += 0.35
        if not word[:1].isalpha():
            value += 0.15
        before_d = low[-2] if n > 1 else ''
        if before_d == 'i':
            value += 0.2
        elif before_d in 'bcdfghjklmpqrstvwxyz' and before_d:
            value -= 0.3
        if n == 1:
            value = -0.78
            if text == 'd':
                value = -0.96 - 0.41 * inside
            elif text == 'D':
                value = -0.78 - 0.33 * inside
        if word.startswith('.') and n > 1:
            value *= 0.6
    elif low.endswith('д'):
        value = -0.95
        if low.endswith('ед'):
            value = -0.3
        elif n == 2 and low[-2] in 'ао':
            value = -0.65
        if word == 'Д' and text[:1].isspace():
            value = -0.75
    elif low.endswith('د'):
        value = -0.5 - 0.3 * inside
    if plural:
        value *= 0.65
    return (doc, text[-1:]), value

