READS = ()

FOR_LIKE = {"für": 0.7, "för": 0.6, "для": 0.65, "untuk": 0.5, "voor": 0.6, "pentru": 0.5,
            "dla": 0.35, "para": 0.3, "basis": 0.6, "foundation": 0.7, "framework": 0.8,
            "underlying": 0.65, "foundations": 0.9, "foundational": 0.9}
NEED = {"necessary", "essential", "crucial", "important", "needed", "need", "required", "useful",
        "suitable", "appropriate", "basis", "framework", "standard", "criteria", "perfect",
        "proposed", "designed", "beneficial", "good", "best", "ideal", "suited"}
SEEK = {"look", "looking", "search", "searching", "ask", "asks", "asked", "wait", "waiting",
        "thank", "thanks", "account", "accounted", "accounting", "responsible", "liable",
        "apply", "applied", "applying", "demand", "request", "love", "pay", "care", "play", "played"}


