    now = word(prefix.token_strings[-1])
    before = word(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
    if now == "for":
        if before in NEED:
            v = 1.7
        elif before in SEEK:
            v = 0.3
        else:
            v = 1.0
    elif now == "to" and before in NEED:
        v = 0.3
    else:
        v = FOR_LIKE.get(now, 0.0)
    return None, v

