programs.sol:
"""A spelling-boundary signal, chiefly after doubled consonants.

Predict a positive signal on short Latin/Cyrillic continuations (or digits)
after a fragment ending in a doubled letter. The gain depends on the type
of repeated letter and falls with fragment length. Common grammatical
endings, and continuations themselves ending in doubled letters, reduce
it. Ordinary consonant clusters give a smaller signal. Initial tokens
have separate offsets for headings, import syntax, comments, the definite
article, PHP opening tag, and the chat-opening marker. Other positions
receive a near-zero baseline. The previous token resets at document boundaries.
"""
import math
import unicodedata
from functools import lru_cache

READS = ()
VOWELS = set('aeiouyаеёиоуыэюя')
LIQUIDS = set('lrлр')
NASALS = set('mnмн')
SIBILANTS = set('szсз')
FRICATIVES = set('fhvфвх')
STOPS = set('bcdgkpqtбгдкпт')
INITIAL_IMPORT_GAIN = {
    'import': 0.82,
    'from': 0.23,
    '#include': 0.41,
}
GRAMMATICAL_ENDINGS = {
    'ed', 'ing', 'ings', 'es', 'ers', 'ion', 'ions',
    'ation', 'ations', 'tion', 'tions',
}


@lru_cache(maxsize=8192)
def spelling(token):
    word = token.strip().lower()
    names = [unicodedata.name(c, '') for c in word]
    alphabet = 0
    if word.isalpha():
        if all('LATIN' in n for n in names):
            alphabet = 1
        elif all('CYRILLIC' in n for n in names):
            alphabet = 2
    doubled = len(word) > 1 and word[-1] == word[-2]
    return word, alphabet, doubled


def letter_gain(letter):
    if letter in LIQUIDS:
        return 0.58
    if letter in SIBILANTS:
        return 0.68
    if letter in FRICATIVES:
        return 0.83
    if letter in NASALS:
        return 0.99
    if letter in STOPS:
        return 1.13
    return 0.29


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    current, alphabet, current_double = spelling(token)
    value = 0.003
    if carry is None or carry[0] != doc:
        value = -0.18 if token[:1].isspace() else -0.09
        initial = token.strip()
        if token == '<|im_start|>':
            value = -0.49
        elif initial and set(initial) == {'#'}:
            value = min(0.7, 0.28 * len(initial) - 0.15)
        elif initial in INITIAL_IMPORT_GAIN:
            value = INITIAL_IMPORT_GAIN[initial]
        elif initial.lower() == 'the':
            value = -0.42 if token[:1].isspace() else -0.27
        elif initial in {'/*', '//'}:
            value = 0.20
        elif initial == '<?':
            value = 0.43
    elif (token and not token[0].isspace()
          and not carry[1][-1:].isspace()):
        previous_token = carry[1]
        previous, previous_alphabet, previous_double = spelling(previous_token)
        continues_word = (token.isalpha() and alphabet != 0
                          and alphabet == previous_alphabet)
        if previous_double and previous_alphabet and (
                continues_word or token.isdigit()):
            gain = letter_gain(previous[-1])
            if previous_token.isupper() and previous[-1] in VOWELS:
                gain += 0.14
            gain *= math.exp(-0.39 * max(0, len(previous) - 3)
                             -0.42 * max(0, len(current) - 2))
            if token in GRAMMATICAL_ENDINGS:
                gain *= 0.44
            if current_double:
                gain *= 0.07
            if current and current[0] == previous[-1]:
                gain *= 0.72
            value += gain
        elif continues_word and previous[-1] not in VOWELS:
            # Ordinary consonant clusters give a smaller continuation signal.
            cluster = len(previous) > 1 and previous[-2] not in VOWELS
            gain = 0.083 if cluster else 0.015
            value += gain * math.exp(
                -0.20 * max(0, len(previous) - 3)
                -1.27 * max(0, len(current) - 2))
    return (doc, token), float(value)

"""A local English collocation approximation.

The main positive spikes are 'so' after do/doing/did/done, 'of' after
end/best/course, and much/many after so/too. Smaller rules cover
related degree and action-result phrases. Pronouns after so or do
receive a negative response. Most other tokens get zero: this omits
the component's many small lexical fluctuations. Two-token memory
resets at document boundaries. Action/completion words also get a
base response there. Numbers are fitted activation sizes.
"""

READS = ()

DO_SO = {'do': 1.91, 'doing': 2.12, 'did': 1.28,
         'done': 1.45, 'does': 1.50}
COPULA_SO = {'is': 0.65, 'are': 0.53, 'was': 0.58, 'were': 0.48,
             'be': 0.78, 'been': 0.61, 'being': 0.62, 'am': 0.31,
             "'s": 0.50, '’s': 0.50, "'m": 0.45, '’m': 0.45}
NEGATION = {'not', "n't", 'n’t', '’t', "'t"}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    prev, before = ('', '') if first else carry[1:]
    word, p, pp = (s.strip().lower() for s in (raw, prev, before))
    state = (doc, raw, prev)
    value = 0.0

    # Spaces and capitalization distinguish word tokens from fragments.
    if raw in (' so', 'so', ' So', 'So'):
        if first:
            value = {' so': 1.50, 'so': 1.18, ' So': 0.80, 'So': 0.87}[raw]
        elif raw == 'so':
            value = 0.18
        elif raw in (' So', 'So'):
            value = 0.02
        elif p in DO_SO:
            value = DO_SO[p]
        elif p in COPULA_SO:
            value = COPULA_SO[p]
        elif p in {'say', 'said', 'saying'}:
            value = 1.0
        elif p in NEGATION or p in {'just', 'more', 'ever'}:
            value = 0.79
        elif p == 'it':
            value = 0.95 if pp in DO_SO else 0.45
        elif p in {'think', 'thought', 'even', 'only', 'become', 'has'}:
            value = 0.55
        elif p == 'if':
            value = 0.43
        elif not p or not any(c.isalnum() for c in p):
            value = 0.09
        elif p in {'and', 'but', 'or'}:
            value = 0.33 if prev.strip()[:1].isupper() else 0.17
        else:
            value = 0.26

    # Completion/boundary and part-purpose expressions ending in 'of'.
    elif raw == ' of':
        if first:
            value = 0.164
        elif p == 'end':
            value = 0.75
        elif p == 'best':
            value = 0.86
        elif p == 'course':
            value = 0.53
        elif p == 'ends':
            value = 0.46
        elif p == 'sake':
            value = 0.67
        elif p in {'beginning', 'start', 'proof', 'interest', 'interests'}:
            value = 0.32
        elif p in {'part', 'parts', 'top', 'bottom', 'side', 'middle',
                   'rest', 'use', 'purpose', 'means', 'help', 'loss',
                   'evidence', 'name', 'case', 'way'}:
            value = 0.18
        elif p == 'most':
            value = 0.28

    elif raw == ' much':
        if p == 'so':
            value = 0.94
        elif p == 'too':
            value = 0.81
        elif p in DO_SO:
            value = 0.76
        elif p in {'very', 'pretty'}:
            value = 0.44
        elif p not in {'a', 'the'}:
            value = 0.17
    elif raw == ' many':
        value = 0.77 if p == 'so' else 0.48 if p == 'too' else 0.10
    elif raw == ' effective':
        if p in {'most', 'more', 'highly'}:
            value = 0.50
        elif p == 'be':
            value = 0.37
        elif p in {'a', 'an', 'the'}:
            value = 0.09
        else:
            value = 0.18
    elif raw == ' best' and p in POSSESSIVES and pp in DO_SO:
        value = 0.65  # 'do one's best'.
    elif p in DO_SO and raw.startswith(' '):
        if word in {'well', 'better', 'what', 'best'}:
            value = 0.74
        elif word == 'good':
            value = 0.63
        elif word in {'things', 'more', 'nothing'}:
            value = 0.49
        elif word in {'something', 'anything', 'everything'}:
            value = 0.32
        elif word in {'you', 'it', 'they'} and p in {'do', 'doing', 'does'}:
            value = -0.23
    elif p == 'so' and raw.startswith(' '):
        if word in {'on', 'long', 'well', 'good', 'often', 'what'}:
            value = 0.53
        elif word in {'far', 'as', 'maybe', 'perhaps'}:
            value = 0.21
        elif word in {'you', 'it', 'they'}:
            value = -0.28
    # Without preceding context, these action/completion words have a
    # substantial base response at the beginning of a document.
    if first and word == 'do':
        value = 0.95 if raw == ' do' else 0.56
    elif first and word == 'doing':
        value = 0.65
    elif first and word in {'best', 'course', 'end'}:
        value = {'best': 0.33, 'course': 0.44, 'end': 0.21}[word]
    return state, float(value)

programs.haiku:
"""Set phrases whose second word lights up (scratch v6).

The component fires on the word that completes a stock two-word phrase: the 'so' of
'do so', the 'much'/'many' of 'so much' / 'too many', the 'of' of 'end of' / 'best of',
and so on. Each phrase gets a fixed value. A few word classes get a default, and a few
phrases that push it slightly negative ('so you', 'any other') are listed too."""
READS = ()

DO_WORDS = {"do", "does", "did", "doing", "done", "to", "can", "will"}
BE_WORDS = {"is", "are", "was", "were", "be", "been", "not", "it", "am"}

# (previous word, word) -> activation, for stock phrases
PHRASES = {
    ("so", "much"): 0.9, ("too", "much"): 0.9, ("so", "many"): 0.8, ("too", "many"): 0.5,
    ("so", "long"): 0.6, ("so", "well"): 0.5, ("very", "much"): 0.45, ("very", "well"): 0.4,
    ("so", "on"): 0.6, ("so", "far"): 0.2,
    ("end", "of"): 0.8, ("best", "of"): 0.8, ("course", "of"): 0.6, ("beginning", "of"): 0.3,
    ("start", "of"): 0.3, ("most", "of"): 0.3,
    ("do", "anything"): 0.3, ("do", "nothing"): 0.3, ("do", "something"): 0.3,
    ("so", "you"): -0.3, ("so", "it"): -0.3, ("so", "they"): -0.25, ("do", "you"): -0.25,
    ("any", "other"): -0.2, ("think", "of"): -0.2, ("one", "of"): -0.1, ("type", "of"): -0.18,
}
# 'of' after nouns of time, place, part or purpose: a weaker lift
OF_WEAK = {"part", "parts", "use", "proof", "interests", "purpose", "top", "rest", "side",
           "loss", "evidence", "means", "full", "help", "sake", "case", "role"}
# 'of' after quantity words is pushed slightly negative
OF_QUANTITY = {"%", "percent", "ratio", "factors", "factor", "years", "some",
               "combination", "lack", "thousands", "majority", "percentage", "frequency", "kind"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if (prev, tok) in PHRASES:
        return carry, PHRASES[(prev, tok)]
    if tok == "so":
        if prev in DO_WORDS:
            return carry, 2.0          # 'do so'
        if prev in BE_WORDS:
            return carry, 0.7          # 'is so good', 'not so'
        return carry, 0.15             # conjunction 'so'
    if tok == "of":
        if prev in OF_WEAK:
            return carry, 0.25
        if prev in OF_QUANTITY:
            return carry, -0.12
    return carry, 0.0

programs.luna:
"""Predict modest bursts on degree/quantity words and partitive 'of' phrases."""
READS = ()

BOUNDARY_NOUNS = {"end", "ends", "course"}
PART_OR_RELATION_WORDS = {"rest", "most", "full", "part", "use", "best", "interest"}
QUANTITY_WORDS = {"much", "many", "enough"}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ""
    word = prefix.token_strings[-1].strip().casefold()

    if word == "so":
        value = 0.14
    elif word in QUANTITY_WORDS:
        value = 0.15
    elif word == "of" and previous in BOUNDARY_NOUNS:
        value = 0.55
    elif word == "of" and previous in PART_OR_RELATION_WORDS:
        value = 0.35 if previous in {"best", "interest"} else 0.20
    else:
        value = 0.0

    return (document, word), value

"""Use the current token alone to predict sparse negative lexical triggers.
The main English cues are 'what' and 'how'; 所 and ところ add related forms."""
READS = ()

WH_WORDS = {"what": -1.0, "how": -0.8, "whatever": -0.85}
EAST_ASIAN_MARKER = "所"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    token = token.strip("\"'([{<.,:;!?“”‘’")
    if token == EAST_ASIAN_MARKER:
        return None, -10.0
    if EAST_ASIAN_MARKER in token:
        return None, -2.0
    if "ところ" in token:
        return None, -2.3
    return None, WH_WORDS.get(token, 0.0)

programs.sol:
"""A negative closing-delimiter detector, strongest on square brackets.

Isolated square closers and closers joined to escaped quotes are strong.
Other attached punctuation, line endings, and empty pairs weaken them.
The preceding token distinguishes names, numeric indices, and backslash
escapes; document position gives a small additional adjustment.

Curly and angle closers have weaker responses. Whitespace, escaped line
breaks and quoted-line starts weaken these further. Predict zero elsewhere,
and reset all state at document boundaries.
"""
READS = ()


def square_strength(token):
    before, after = token.rsplit(']', 1)
    if '[' in before:                 # Opening and closing brackets share a token.
        return 0.65
    if not after:
        if before.endswith('\\"'):
            return 4.2
        if before.endswith('()'):
            return 3.15
        if before.endswith('.'):
            return 2.55
        if before.endswith((')', '"', ']')):
            return 2.5
        if before.isspace() or before.endswith("'"):
            return 2.8
        return 3.3
    if after.isspace():
        return 1.1 if after.count('\n') < 2 else 0.75
    first = after[0]
    if first in ',.:;=':
        strength = {',': 1.5, '.': 1.3, ':': 1.35, ';': 0.9, '=': 1.3}[first]
        if '\n' in after:
            strength *= 0.65 if first != ',' else 0.95
        if '"' in after:
            strength *= 0.55
        return strength
    if first in '(+':
        return 2.8
    if first == '{':
        return 1.9
    if first in '^*/-\\':
        return 2.2
    if first == ')':
        return 0.9 if len(after) == 1 else 0.45
    if first in "\"'":
        return 1.5 if len(after) == 1 else 0.8
    return 3.2 if first.isalpha() else 1.3


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position, escaped_line_end = '', 0, False
    else:
        _, previous, position, escaped_line_end = carry
        position += 1
    word = previous.strip()
    value = 0.0
    if '】' in token or '］' in token:
        value = -3.0 + 0.5 * word.isnumeric()
    elif ']' in token:
        strength = square_strength(token)
        adjustment = -0.5 / (1 + position / 70)
        if word.isalpha():
            adjustment += 0.2 if previous.startswith(' ') else -0.2
            adjustment -= 0.25 * word[:1].isupper()
        adjustment += 0.3 * word.isnumeric()
        adjustment -= 0.65 * ('[' in previous)
        adjustment += 0.4 * (']' in previous)
        adjustment += 1.1 * previous.endswith('\\')
        adjustment += 1.4 * (position < 2)
        value = -strength + adjustment * strength / 3.2
    elif '}' in token:
        before, after = token.rsplit('}', 1)
        value = -0.7
        if '\n' in after:
            value = 0.0
        elif after.startswith((',', ';')):
            value = -0.2
        elif after.startswith(('\\', '$', '(', ')', '{', '_{')):
            value = -0.35
        elif not after or after == '`':
            if not any(c.isalnum() for c in previous):
                value = -0.25
            if (previous.isspace() or previous.endswith('\n')
                    or escaped_line_end or position == 0):
                value = 0.15
            if before.endswith('}'):
                value = -0.9
            elif before.endswith('{'):
                value = -0.27
            elif before.endswith(('\"', "'")):
                value = -0.6
    elif ('>' in token and '<' not in token
          and '->' not in token and '=>' not in token):
        value = -0.6
        if (previous.isspace() or previous.endswith('\n')
                or token.startswith(' >')):
            value = 0.15
        elif '\n' in token:
            value = -0.3
        elif ',' in token or word.isnumeric():
            value = -0.2
        elif not any(c.isalnum() for c in previous):
            value = 0.1
        elif '<' in previous:
            value = -1.15
    elif token in ('』', '」'):
        value = -0.4
    escaped_line_end = token.endswith(('\\n', '\\t')) or (
        token in ('n', 't') and previous.endswith('\\'))
    return (doc, token, position, escaped_line_end), float(value)

programs.haiku:
"""Closing-bracket detector for one layer-0 MLP direction. It responds negatively to
closing brackets: strongly to a square bracket ']' that closes an index or list
(x[0], a[i], [1, 2]), more so when the bracket is short than when it holds a long list;
weakly when the ']' is followed by punctuation or a newline ('],' '].' ']\\n'); and weakly
to closing braces and angle brackets. Everything else is 0."""
READS = ()
BRACE_CLOSERS = {"}", "}}", ">", ">>", "}\\"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    t = prefix.position
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        opens = []  # positions of unmatched '[' in this document
    else:
        opens = list(carry)
    value = 0.0
    if "[]" in tok:
        pass  # empty brackets: no response
    elif "]" in tok or "】" in tok:
        gap = t - opens.pop() if opens else 99
        if tok.endswith(("]", "】")) or tok.startswith("]("):
            value = -4.0 if gap <= 3 else -3.0
        else:
            value = -1.4
    elif tok.strip() in BRACE_CLOSERS:
        value = -0.5
    if "[" in tok and "[]" not in tok:
        opens.append(t)
    return opens, value

programs.luna:
"""Approximate a sparse negative response to closing punctuation.

A token with a square-bracket closer gets the strongest response; spacing
and nearby punctuation adjust it. Tokens containing } or > get a smaller
negative response, and all other tokens get zero.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    visible = token.strip()

    if "】" in token:
        return None, -3.325

    if "]" in token:
        if visible in ("]", "]]"):
            if "\n" in token:
                return None, -1.235
            if token[:1].isspace():
                return None, -2.47
            return None, -3.325
        if visible.endswith("("):
            return None, -2.565
        if visible.endswith((",", ".")):
            return None, -1.425
        return None, -1.615

    if "}" in token:
        return None, -0.5225
    if ">" in token:
        return None, -0.266
    return None, 0.0

