READS = ()
FUNCTION_WORDS = {'will', 'while', 'still', 'until'}
FILE_NOUNS = {'file', 'files', 'filename', 'filenames', 'filter', 'filters'}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
