        before, after = text[:i], text[i + 2:]
        letters_before = sum(c.isalpha() for c in before)
        if text in FUNCTION_WORDS or text == 'april':
            value = -0.06
        elif text in FILE_NOUNS:
            value = -0.3 if text in {'file', 'filename'} else -0.15
        elif before.endswith('a'):
            value = -0.09
        elif not before and not after:
            titlecase = raw.istitle()
            value = -4.65 if raw == raw.strip() and not titlecase else -2.72
            previous = ''
            if len(prefix.token_strings) > 1 and (
                    prefix.document_ids[-1] == prefix.document_ids[-2]):
                previous = prefix.token_strings[-2].lower()
            if raw == raw.strip() and not titlecase:
                if previous.endswith('o'):
                    value = -3.35  # The preceding token makes an 'oil' spelling.
                elif previous.endswith('e'):
                    value = -4.11
                elif previous.endswith('qu'):
                    value = -5.85
        elif not after:
            if before.endswith('o'):
                value = -1.16
            elif before.endswith('e') and letters_before > 1:
                value = -1.05
            elif text == '.util':
                value = -3.3
            elif text.strip('/-_’\"\'') == 'util' and (
                    raw[0].isspace() or raw.istitle() or text != 'util'):
                value = -1.55
            else:
                value = (-3.54, -3.0, -1.9, -1.5, -0.6)[
                    min(5, max(1, letters_before)) - 1]
        elif after.startswith('l'):
            value = -0.45
        elif not before:
            value = (-1.88, -1.33, -1.10, -0.73)[min(4, len(after)) - 1]
        elif letters_before == 1:
            value = -0.61
        else:
            value = -0.13
    elif text.endswith('yl'):
        value = -1.0
    elif text.startswith('ил'):
        value = -1.8 if text in {'ил', 'иль'} else -0.6
        if text == 'или':
            value = -1.3
        if raw.startswith(' ') and text == 'или':
            value = 0.0  # Russian 'or', a whole function word.
    elif text.startswith('ıl'):
        value = -1.4 if len(text) <= 3 else -0.6
    elif text.endswith('ил') and len(text) <= 3:
        value = -1.7
    elif text.endswith('يل') and len(text) <= 3:
        value = -1.2
    elif text == 'イル':
        value = -1.35
    elif text == '일':
        value = -1.1
    elif text == '필':
        value = -2.0
    return None, float(value)

