"""A lexical shape/form/type detector, with a one-token continuation.

Shapes have the largest response, forms a smaller one, and types a smaller
one again. Inflections, translated roots, and programming type/shape names
also trigger it. Leading punctuation and capitalization affect the strength.
The response sometimes continues into a following article, 'of', or suffix.
Unrecognized tokens receive zero; weak, unrelated lexical responses are omitted.
"""

READS = ()

SHAPE_WORDS = {'shape', 'shapes', 'shaped', 'shaping'}
FORM_WORDS = {'form', 'forms', 'formed', 'forming', 'formation', 'formations'}
ARTICLES = {'a', 'an', 'the'}


def lexical(token):
    text = token.strip()
    word = text.lstrip('._-/()<>\\').casefold()
    boundary = token.startswith(' ')

    if word in SHAPE_WORDS:
        if text.startswith('-'):
            return 4.05
        if word in {'shaped', 'shaping'}:
            return 3.0 if word == 'shaped' else 2.8
        return 3.9 if boundary else 3.2
    if word == 'reshape':
        return 0.85
    if word in FORM_WORDS:
        if word == 'form':
            return 1.47 if boundary and text == 'form' else 1.1
        return 1.65 if boundary else 1.05
    if word == 'former':
        return 0.65
    if word in {'forma', 'forme', 'formas'}:
        return 2.0 if boundary and word != 'formas' else 1.05
    if word == 'formato':
        return 0.6
    if word == 'morph':
        return 1.3
    if word in {'morphology', 'omorphic', 'iform', 'waveform'}:
        return 0.8
    if word.startswith(('transform', 'conform', 'deform')):
        return 0.65
    if word == 'typeof':
        return 2.55
    if word in {'type', 'dtype', 'typename'}:
        if text.startswith('-'):
            return 1.3
        return 0.7 if text.startswith('_') else 1.05
    if word in {'types', 'dtypes'}:
        return 0.7
    if word in {'isinstance', 'prototype', 'prototypes', 'otype', 'otypes', 'etypes'}:
        return 0.9
    if word == 'otyping':
        return 1.5
    if word.endswith('type') or word.endswith('types'):
        return 0.9
    if word in {'typ', 'typed', 'typedef'}:
        return 0.7
    if word in {'typing', 'typical', 'typescript'}:
        return 0.4

    # 形: shape/form; 型 and Korean 형: pattern/type.
    if text == '形':
        return 6.5
    if text in {'型', '형'}:
        return 4.15
    if text == '形状':
        return 4.0
    # Shape, form/format, formation, and terrain respectively.
    if text == '形式':
        return 1.9
    if text.startswith('形成'):
        return 2.85
    if text == '地形':
        return 4.7
    if '形' in text:
        # Situation and description are weaker uses of the same root.
        if '情形' in text:
            return 0.5
        if '形容' in text:
            return 1.3
        return 3.25 if len(text) == 2 and text.endswith('形') else (
            2.8 if len(text) == 2 else 1.6
        )
    if '型' in text:
        # Model, type, then size/styling/hairstyle compounds.
        if '模型' in text:
            return 0.2
        if '类型' in text:
            return 1.0
        return 1.9 if text in {'大型', '造型', '发型'} else (
            1.25 if len(text) == 2 else 0.75
        )
    if text == '状':
        return 0.9
    # Vietnamese hình and Russian образ / форм: image/form roots.
    if word == 'hình':
        return 2.1
    if word == 'образ':
        return 1.5 if boundary else 1.2
    if word.startswith('форм'):
        return 1.0 if boundary else 0.6
    if word == 'terrain':
        return 1.4
    if word == 'arch' and boundary:
        return 0.6
    if word in {'irregular', 'graphics', '身材'}:
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().casefold()
    before = previous.strip().lstrip('._-').casefold()
    value = lexical(token)

    # A multibyte character may become readable only at its last byte token.
    if '\ufffd' in token:
        last = prefix.text_prefixes[-1][-1:]
        if last in {'形', '型'}:
            value = 6.5 if last == '形' else 4.15

    if not token[:1].isspace():
        if before.endswith('sh') and word in {'ape', 'apes', 'aped', 'aping'}:
            value = 4.2 if word != 'aping' else 3.0
        elif before in {'form', 'morph'} and word in {'ing', 'ed', 's'}:
            value = 1.4

    if word == 'of':
        if before in {'shape', 'shapes'}:
            value = 2.4
        elif before in FORM_WORDS:
            value = 1.1
        elif before in {'type', 'types'}:
            value = 0.3
    elif word in ARTICLES and before in FORM_WORDS | {'shaping'}:
        value = {'a': 0.83, 'an': 0.65, 'the': 0.63}[word]

    return (doc, token), float(value)

programs.luna:
"""Predict the component's clearest lexical responses: shape, form, and type.

Shape words get the largest positive pulse; form and type words get smaller
ones. The rule ignores context and leaves other, less predictable responses
silent.
"""
READS = ()

FORM_WORDS = {
    "form", "forms", "formed", "forming", "formation", "formations",
    "forma", "format", "formats", "formatted", "formatting",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    partial = "" if carry is None or carry[0] != doc else carry[1]
    completed = ""
    for char in prefix.token_strings[-1]:
        if char.isalnum() or char == "_":
            partial += char.casefold()
        else:
            if partial:
                completed = partial
            partial = ""
    word = partial or completed
    if word.startswith("shape"):
        value = 3.2
    elif word in FORM_WORDS:
        value = 1.0
    elif word == "typeof":
        value = 2.4
    elif word.startswith("type") or word == "dtype":
        value = 1.0
    else:
        value = 0.0
    return (doc, partial), value

programs.sol:
"""Mostly an orthographic 'ux' detector, strongest on short word pieces.

Isolated UX and short stems (aux, lux, flux) have large positive responses.
Longer words and French plural/adjectival endings respond more weakly.
Byte escapes, short x-ending pairs, Greek xi and two Cyrillic spellings
are weaker x-like triggers; u with a ring or grave accent also responds.
A preceding vowel distinguishes weak French endings from stronger stems.
The characters 兴/興 (arising/enthusiasm) and 欲 (desire) are secondary
positive triggers, regardless of their meaning in context. The social
adjective and Chinese society nouns receive negative predictions.
Unlisted spellings get zero; weaker token-specific effects are not modeled.
"""
READS = ()


def spelling_value(token):
    word = token.strip().lstrip('_(')
    lower = word.lower()
    if word == 'UX':
        return 2.1 if token[:1].isspace() else 4.7
    if lower == 'ux':
        return 3.9
    if lower == 'aux':
        return 3.0
    if lower == 'lux':
        return 3.1 if token[:1].isspace() or word[0].isupper() else 5.6
    if lower == 'flux':
        return 3.0 if token.startswith('_') else 3.8
    if lower == 'mux':
        return 1.5 if token[:1].isspace() else 3.1
    if lower.startswith('auxili'):
        return 2.4
    if lower in ('influx', 'reflux'):
        return 1.6
    if lower.startswith('luxur'):
        return 1.25
    if lower in ('oux', 'iaux', 'ieux'):
        return 1.0
    if lower == 'faux':
        return 2.0
    if lower in ('luxe', 'uxe'):
        return 1.0
    if word == '\\x':
        return 1.1
    if word == '\\xa':
        return 0.33
    if word in ('ξ', 'Ξ'):
        return 0.58
    if word in ('ух', 'ех'):
        return 0.52
    if len(word) == 2 and word.isascii() and word.isalpha() and lower[-1] == 'x':
        return 0.2 if lower[0] in 'aeiou' else 0.35
    if word in ('ů', 'ù'):
        return 0.65
    if word in ('兴', '興', '欲'):
        return 1.45
    if lower in ('social', 'socially'):
        return -0.4
    if word in ('社会', '社會'):
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = spelling_value(token)
    previous = ''
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]

    # After a/e, ux often completes a French -aux/-eux ending.
    # A consonant before ux generally gives a stronger response.
    if token == 'ux':
        value = 3.1 if previous[-1:] in ('a', 'e', 'œ') else 5.8
    elif token == 'aux':
        value = 2.5 if previous[-1:].islower() else 4.6
    elif token == 'Aux':
        value = 4.4
    elif token == ' ux':
        value = 3.0
    return None, float(value)

"""A spelling-based detector of agent, instrument, and operator nouns.

Latin -ator/-itor/-ctor endings dominate the negative response, particularly
when emitted as a short suffix token. Whole role/tool names, English -er
agents, and analogous Romance, Cyrillic, and Chinese endings are weaker.
Identifier punctuation is stripped; long whole words are attenuated.
No history is used. Plurals are attenuated and capitals amplified.
"""
READS = ()

MATH = {'factor', 'factorial', 'vector', 'tensor', 'denominator'}
COMMON_ROLES = set('actor doctor monitor visitor competitor investor ancestor '
                   'pastor sponsor'.split())
ROLE_TOOLS = set('''
author builder compiler founder finder manufacturer teacher manager writer
provider producer supplier interpreter solver resolver serializer observer
adapter converter identifier designer employer transformer photographer
developer controller logger lexer adviser handler loader encoder renderer
helper reader maker caregiver lawmaker minister commissioner container cooker
secretary governor ambassador cylinder guardian catalyst conveyor factory
repository physician
'''.split())
# (noun ending, short bare suffix response, whole-word response)
ENDINGS = (
    ('ator', 4.4, 2.35), ('itor', 3.9, 2.35), ('ctor', 3.9, 2.0),
    ('utor', 3.1, 2.3), ('ktor', 3.7, 2.3), ('tor', 2.6, 2.4),
    ('isor', 3.4, 2.4), ('sor', 2.4, 1.7),
)


def strength(word, fragment):
    if word in MATH:
        return 1.3
    if word in COMMON_ROLES:
        return 2.4 if word == 'actor' and fragment else 1.05
    if word in {'receptor', 'detector', 'reactor', 'sensor', 'processor',
                'professor', 'cursor', 'precursor', 'compressor'}:
        return 1.4
    if (word in {'generator', 'iterator', 'creator', 'regulator', 'validator'}
            or word.endswith(('editor', 'structor', 'protector',
                              'executor', 'functor'))):
        return 3.35
    if word == 'ator':
        return 5.2
    if word in {'histor', 'territor', 'stor', 'sor'}:
        return 0.4
    for ending, suffix_value, word_value in ENDINGS:
        if word.endswith(ending):
            return (suffix_value if fragment
                    else word_value * min(1, 10 / len(word)))
    if word in {'setter', 'notifier', 'publisher', 'promoter', 'lecturer'}:
        return 1.6
    if word in ROLE_TOOLS or word in {'izer', 'ifier', 'imiter', '作者'}:
        return 0.85
    if word in {'or', 'eur'}:
        return 0.65 if fragment else 0.0
    if word in {'ador', 'adora', 'ateur', 'iteur', 'atore', 'atori', 'itori'}:
        return 2.1
    if word in {'атор', 'ектор', 'отор'}:
        return 4.2
    if word == 'тор':
        return 2.4
    if word in {'атель', 'итель', 'ителя', 'ителей'}:
        return 1.05
    if word == 'ор':
        return 0.43
    if word in {'atory', 'itorial', 'atorial', 'itory', 'ulatory',
                'regulatory', 'actory'}:
        return 2.3
    if word in {'器', '者'}:
        return 1.7 if word == '器' else 0.3
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    clean = token.strip().lstrip('_-./(@')
    word = clean.lower()
    plural = word.endswith('s')
    if plural:
        word = word[:-1]
        if word.endswith('adore'):
            word = word[:-1]
    fragment = (token == clean and len(word) <= 7
                and (clean.islower() or clean.isupper()))
    magnitude = strength(word, fragment)
    if plural:
        magnitude *= 0.78
    if clean.isupper():
        magnitude *= 1.25
    elif clean[:1].isupper() and word in ROLE_TOOLS:
        magnitude *= 1.15
    return None, float(0.002 - magnitude)

programs.haiku:
"""Layer-0 MLP component 3182: a "tyranny and oppression" word detector.

This component is diffuse: most of its small activations come from many ordinary tokens,
so a short word list can only explain a little of it. The clearest signal is negative
on words about oppressive rule and atrocity (tyranny, dictatorship, regime, persecution,
murder, ghetto, and the Chinese 政权 regime, 祸 calamity, 沦陷 / 沦落 'fall into
occupation / misery'). It is weaker on the political vocabulary around them
(government, rebel, enslaved, prison) and on a few hedging words (any, either, both,
several, too). A few neutral-to-positive words (originally, similar, possible, does)
are slightly positive. Everything else predicts 0.
"""

READS = ()

ATROCITY = {
    "tyranny", "tyr", "tyrant", "oppression", "oppressed", "dictatorship", "persecution",
    "persecuted", "murdered", "murder", "massacre", "ghetto", "政权", "祸", "沦", "陷",
}
POLITICS = {
    "regime", "government", "governments", "governance", "governor", "governors",
    "rebel", "rebels", "enslaved", "imprisonment", "imprisoned", "nazi", "nazis",
    "cruel", "suffer", "suffered", "逃", "灭", "杀", "死",
}
HEDGES = {"any", "either", "both", "several", "further", "too", "being", "many", "only"}
POSITIVE = {"originally", "initially", "similar", "possible", "does", "describe", "army"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in ATROCITY:
        return carry, -0.35
    if word in POLITICS:
        return carry, -0.13
    if word in HEDGES:
        return carry, -0.07
    if word in POSITIVE:
        return carry, 0.07
    return carry, 0.0

programs.sol:
"""Predict a document-opening formatting response, not general semantics.

Bare headings, source-code declarations, and capitalized sentence openers
are negative. Leading spaces and lowercase word fragments are positive.
The same token-shape response is largest at the first token, then quickly
fades with document position. The second token also gets a small echo of
the first token. Constants are fitted class averages. Most later lexical
variation is deliberately left unexplained.
"""
from math import exp

READS = ()

# Familiar syntax and document labels with strong opening responses.
OPENING_SYNTAX = {
    '#': -1.06,
    '##': -1.30,
    'package': -1.11,
    'import': -0.84,
    'from': -0.57,
    'Title': -0.97,
    '<|im_start|>': -0.61,
    '<|im_end|>': -0.89,
    '<|endoftext|>': -0.16,
    '<tool_call>': -1.23,
    '<tool_response>': -0.75,
}
SENTENCE_LINKS = {
    'As', 'At', 'By', 'For', 'On', 'With', 'After', 'Since',
    'This', 'There', 'When', 'Where', 'Who', 'Which', 'Do', 'Will',
    'Hello', 'Hi', 'Welcome', 'It',
}
FUNCTION_WORDS = {
    'a', 'an', 'the', 'of', 'to', 'on', 'at', 'by', 'and',
    'with', 'was', 'were', 'as', 'you', 'your', 'their',
}


def opening(s):
    if s in OPENING_SYNTAX:
        return OPENING_SYNTAX[s]
    if s.startswith('#!/'):
        return -1.06
    if s.startswith('#include'):
        return -0.83
    if s.startswith('#'):
        return -0.45
    if s.startswith(('/*', '<?', '"""')):
        return -0.66
    if s.startswith(('//', "'''", '---', '```', '**')):
        return -0.29
    if s.startswith(('<think>', '</think>', '</tool_')):
        return -0.50
    if s in {'using', 'def', 'export', 'theorem', 'namespace', 'public'}:
        return -0.30
    if s in {'class', 'const', 'function', 'var', 'module'}:
        return -0.06
    if s in {'A', 'An', 'The'}:
        return -0.51 if s == 'A' else -0.65
    if s == 'What':
        return -0.98
    if s in {'In', 'How', 'Why'}:
        return -0.66
    if s in {'I', 'We', 'You', 'Is', 'Are', 'Can', 'Could',
             'Does', 'Would', 'Should'}:
        return -0.49
    if s in SENTENCE_LINKS:
        return -0.33
    if s in {'He', 'She', 'They', 'That', 'These', 'Those'}:
        return -0.10
    if s.isspace():
        if s == '\n':
            return -0.18
        if '\n' in s or '\r' in s or not s.isascii():
            return -0.06
        return 0.11 if '\t' in s else 0.40 / len(s) ** 0.5
    z = s.strip()
    if not z:
        return 0.0
    if z.isascii() and z.isdigit():
        return 0.04 if z == '0' else -0.08
    if s.startswith(' '):
        if z in {'The', 'This'}:
            return 0.72
        if z == 'in':
            return -0.21
        if z in FUNCTION_WORDS:
            return -0.07
        if z in {'is', 'it', 'that', 'or', 'for', 'not', 'from', 'into'}:
            return 0.03
        return 0.23 if z[0].isupper() else 0.12
    if z.isascii() and z.isalpha():
        if z.islower():
            return 0.22
        if len(z) == 1:
            return -0.05
        return 0.03 if z.isupper() else -0.11
    if all('\u4e00' <= c <= '\u9fff' for c in z):
        return -0.13
    if z[0] in '[<"“「【«《¿':
        return -0.38
    if '\n' in z:
        return 0.0
    if z == ':':
        return 0.29
    if z == '.':
        return 0.05
    return -0.10 if z[0].isupper() else 0.10


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening(prefix.token_strings[-1])
        return (doc, 0, value), float(value)
    _, position, first_value = carry
    position += 1
    value = 0.19 * exp(-position / 6.0) * opening(prefix.token_strings[-1])
    value += 0.035 * exp(-position)
    if position == 1:
        value += 0.071 * first_value
    return (doc, position, first_value), float(value)

programs.haiku:
"""Layer-0 MLP down-projection, hidden unit 3183 (`layers.0.mlp.down_proj:3183`).

In plain terms: this unit is nearly silent inside running text. Most of its variance
sits at the first token of a document (or of a packed row), where the model has no
earlier context, so the unit reacts to what kind of token opens the text:

- a chat control token (<|im_start|>, <|im_end|>, <tool_response>, ...), or a code or
  markup opener (#, ##, #include, package, import, //, /*, <?, [, ---): strongly negative;
- "The" written with no leading space: strongly negative, and other capitalised words
  with no leading space ("In", "What"): mildly negative;
- a lone space, or a word with a leading space (" The", " of"): positive;
- a lowercase word fragment with no leading space: mildly positive;
- other punctuation (":", ")", "(", ","): weakly positive; digits: weakly negative.

Every later position is predicted as 0, the mean. That leaves out the diffuse,
token-specific variation of the rest of the text, which is most of the variance but has
no simple description.
"""

READS = ()

CONTROL_PREFIXES = ("<|", "<tool_")
CODE_OPENERS = ("#", "//", "/*", "<?", "[", "---", "package", "import", "'use")


def first_token_value(s):
    """The activation when the first token of a document has text `s` (decoded alone)."""
    if s.startswith(CONTROL_PREFIXES):
        return -0.6
    if s.startswith(CODE_OPENERS):
        return -0.9
    if s == " ":
        return 0.4
    if s[:1] == " ":
        return 0.25 if s[1:2].isupper() else 0.09
    if s == "The":
        return -0.6
    if s[:1].isupper():
        return -0.2
    if s[:1].islower():
        return 0.13
    if s[:1].isdigit():
        return -0.08
    return 0.1


def step(carry, prefix, upstream):
    new_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not new_document:
        return carry, 0.0
    return carry, first_token_value(prefix.token_strings[-1])

programs.luna:
"""Estimate this small component only at document starts, where its layer-0 response is
most consistent. Its strongest written-form cues are chat markers, code/markup headers, and
common English openers; elsewhere its activation is too context-sensitive to predict."""
import unicodedata

READS = ()

ENGLISH_OPENERS = {
    "The", "A", "An", "This", "That", "These", "Those",
    "In", "On", "At", "For", "We", "They", "There",
    "What", "When", "Where", "Who", "How", "Why",
}


def step(carry, prefix, upstream):
    t = prefix.position
    if t and prefix.document_ids[t] == prefix.document_ids[t - 1]:
        return None, 0.0

    piece = prefix.token_strings[-1]
    if piece.startswith("<|im_start|>"):
        return None, -0.61
    if piece.startswith("#"):
        return None, -1.0
    if piece == "package":
        return None, -1.11
    if piece in {"from", "import", "using"}:
        return None, -0.7
    if piece.startswith(("<?", '\"\"\"')):
        return None, -0.7
    if piece in ENGLISH_OPENERS:
        return None, -0.5
    if not piece:
        return None, 0.0
    if piece.isspace():
        return None, 0.4

    # Leading spaces are common tokenizer word boundaries and have their own response.
    category = unicodedata.category(piece[0])
    means = {
        "Zs": 0.12, "Lu": -0.21, "Ll": 0.14, "Po": -0.17,
        "Nd": -0.09, "Lo": -0.11, "Sm": -0.57, "Cc": -0.07,
        "Pe": 0.13, "Pc": 0.16, "Ps": 0.14, "Pd": 0.08,
        "So": 0.13,
    }
    return None, means.get(category, 0.0)

programs.haiku:
"""layers.0.mlp.down_proj:3184 — an "into" detector.

This component writes a large value into the residual stream on the word "into"
(" into", "into", "Into"), a smaller one on "onto", and a moderate one on the
directional prepositions "toward(s)" and "upon", on the arrow "->", and on the
Chinese/Vietnamese words for "into" (进入, 投入, vào ...). Everywhere else it is
(almost) silent. Its size depends only on the current token, not on context.

Main program: look at the current token only; return a fixed value from a small table.
"""

READS = ()

# The word "into" (with or without a leading space, any capitalisation, and the
# identifier form "_into"): the strongest response.
INTO = 4.8
# "onto" is a close relative of "into" ("on to a surface").
ONTO = 3.1
# Other directional prepositions and the arrow used as "maps to / becomes".
DIRECTIONAL = {"toward": 0.75, "towards": 0.7, "upon": 0.5}
ARROW = 0.7
# "into" in other languages: 进入 (enter), 投入 (put into), 進入, vào (Vietnamese).
FOREIGN_INTO = {"进入": 0.9, "進入": 0.66, "投入": 0.78, "投入到": 0.97, "vào": 1.1}


def value_of(token: str) -> float:
    word = token.strip().strip("_.").lower()
    if word == "into":
        return INTO
    if word == "onto":
        return ONTO
    if token.endswith("->"):
        return ARROW
    if word in DIRECTIONAL:
        return DIRECTIONAL[word]
    return FOREIGN_INTO.get(token.strip(), 0.0)


def step(carry, prefix, upstream):
    return carry, float(value_of(prefix.token_strings[-1]))

programs.luna:
"""Approximate the positive response to English transition and direction markers."""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in {"into", "onto"}:
        value = 4.8 if word == "into" else 3.1
    elif word in {"toward", "towards", "upon"}:
        value = 0.7 if word.startswith("toward") else 0.5
    elif word in {"->", "→"}:
        value = 0.7
    else:
        value = 0.0
    return None, value

"""Give common relation words a small positive activation estimate."""
READS = ()

RELATION_WORDS = frozenset({
    "in", "for", "on", "at", "during", "into", "over", "with",
    "above", "across", "在", "در",
})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    return None, 0.24 if word in RELATION_WORDS else 0.0

programs.sol:
"""Recognize indefinite choice, especially 'any' and unspecified things/people.

English indefinite words get fixed positive responses, largest for 'any'.
A few equivalents in Chinese, German, Romance languages and Russian are also
recognized.  Case, word spacing and attached code punctuation change the scale;
'For any' has a smaller response and 'without any' a larger one.
All other tokens get a zero baseline. This is an approximation to word
spellings and two common phrases, not a full analysis of their meanings.
"""

