    'anything': 1.76,
    'anyone': 1.22,
    'anybody': 1.31,
    'anywhere': 1.08,
    'anytime': 0.75,
    'anymore': 1.30,
    'anyway': 0.44,
    'something': 1.50,
    'someone': 0.77,
    'somebody': 0.74,
    'somewhere': 0.31,
    'sometime': 0.13,
    'sometimes': 0.13,
    'everything': 0.27,
    'everyone': 0.19,
    'everybody': 0.25,
    'nothing': 0.24,
    'ever': 0.23,
