            if spelling == 'Any':
                value = 1.72
            elif spelling == 'ANY':
                value = 1.75 if token.startswith(' ') else 1.05
            elif not token.startswith(' '):
                value = 1.21
        elif not token.startswith(' '):
            value *= 0.83
    elif word.lstrip('<.:_-') == 'any':
        value = 1.45
    elif word in SOMETHING:
        value = 0.60
    elif word in ANY:
