"""Layer-0 MLP down-projection, component 3187: an "any"-word detector.

It reads the token at the current position and writes a value that is large when
that token is an English "any" word or "something". Strongest is the bare word
"any" (about 1.9; "Any" and "ANY" about 1.7). The "any" compounds anything, anyone,
anybody, anywhere and anymore give about 1.2 to 1.7, and "something" about 1.5.
"someone" and "somebody" give about 0.8. Weaker responses (0.2 to 0.6) go to
"anyway", "yet", "ever", "everything", "nothing", "somewhere", and to the
any-like words of other languages (любой, cualquier, etwas, 任何). Every other
token predicts 0. The program has no memory: it does not need the earlier text.
"""

READS = ()

# Activation level per word. Keys are words with surrounding spaces removed.
LEVEL = {}
for w in ["any", "Any", "ANY", "<any"]:
    LEVEL[w] = 1.9
for w in ["anything", "Anything", "anyone", "anybody", "anywhere", "anymore"]:
    LEVEL[w] = 1.4
for w in ["something", "Something"]:
    LEVEL[w] = 1.5
for w in ["someone", "Someone", "somebody"]:
    LEVEL[w] = 0.8
for w in ["anyway", "Anyway", "everything", "nothing", "ever", "yet", "somewhere"]:
    LEVEL[w] = 0.3
for w in ["любой", "любом", "люб", "cualquier", "etwas", "任何", "有任何"]:
    LEVEL[w] = 0.6


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    return carry, LEVEL.get(word, 0.0)

programs.luna:
"""A small detector for indefinite words, especially the frequent 'any' family.

These words are the rare, large positive responses visible in sampled firings;
ordinary tokens are predicted to contribute approximately nothing.
"""
READS = ()

ANY_WORDS = {
    "any", "anyone", "anybody", "anything", "anywhere",
    "anytime", "anyplace", "anyhow",
}
LOW_ANY_WORDS = {"anyway"}
SOME_WORDS = {
    "something", "someone", "somebody", "somewhere",
    "somehow", "sometime",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip("<>")
    if word in ANY_WORDS:
        if word == "any":
            return None, 1.95
        if word == "anyone":
            return None, 1.35
        if word == "anything":
            return None, 1.67
        return None, 1.45
    if word in LOW_ANY_WORDS:
        return None, 0.5
    if word in SOME_WORDS:
        return None, 1.5 if word == "something" else 0.8
    if word in {"etwas", "任何人", "有任何"}:
        return None, 0.95
    return None, 0.0

programs.sol:
"""A token-boundary-sensitive detector for short endings containing t.

It responds strongly to isolated t/T and vowel-less t-ending fragments,
less to common English final clusters, and specially to 'at', 'not', and
negation contractions. The previous token distinguishes contraction stems,
word continuations, and n completing a split newline escape. Most longer
words and unrelated tokens are silent; this does not detect every final t.
A few single-letter t counterparts in other scripts also get small responses.
Repeated backslashes damp the split-newline response.
"""
import math
import re
import unicodedata

READS = ()
VOWELS = set('aeiou')
COMMON_FINAL_CLUSTERS = {'ct', 'pt', 'ft', 'ht', 'tt'}
RARE_FINAL_CLUSTERS = {'dt', 'mt', 'wt', 'vt', 'jt'}
VOWEL_RT_RESPONSES = {
    'a': 0.0,
    'e': 0.64,
    'i': 1.5,
    'o': 0.31,
    'u': 0.88,
}


def terminal_t(s, previous=''):
    word = s.strip()
    core = re.sub(r'^[^\w]+|^_+', '', word)
    low = core.lower()
    prev = previous.strip()
    stem = prev.lower()
    if word.lower() in ("'t", '’t'):
        if stem == 'couldn':
            value = 0.52
        elif stem in ('wouldn', 'shouldn', 'weren', 'hadn'):
            value = 0.72
        elif stem in ('don', 'won', 'haven'):
            value = 0.75
        elif stem in ('can', 'doesn', 'didn', 'isn', 'wasn', 'hasn'):
            value = 0.98
        else:
            value = 0.88
        return value + (0.25 if prev[:1].isupper() else 0.0)
    # Other scripts' single-letter counterparts of Latin t.
    if core == 'Т':
        return 0.44
    if core == 'т':
        return 0.27 if s[:1].isspace() else 0.18
    if core == 'ت':
        return 0.27 if s[:1].isspace() else 0.54
    if core == 'ท':
        return 0.59
    if low == 'not':
        if stem in ('does', 'did', 'shall'):
            return 0.73
        if stem in ('should', 'can', 'but', 'will'):
            return 0.64
        if stem in ('am', "'m", '’m', 'or', 'if', 'could', 'need'):
            return 0.40
        return 0.54
    if low == 'cannot':
        return 0.29
    if low == 'at':
        if core.isupper():
            return 0.53
        if core[:1].isupper():
            return 0.96
        boundary = s != core or not previous[-1:].isalpha()
        return 0.81 if boundary else 0.30
    if low == 't':
        if s in ('t', 'T'):
            continuation = previous[-1:].isalpha()
            if continuation and not previous.isascii():
                return 1.25 if s == 't' else 1.43
            if s == 'T':
                return 1.90 if continuation else 1.48
            return 1.76 if continuation else 1.63
        if s == '\\t':
            return 1.20
        if s[:1] in './':
            return 1.72 if core == 't' else 1.39
        if s[:1].isspace() and core == 'T':
            return 1.15
        return 1.31
    if not low.endswith('t') or not core.isalpha():
        return 0.0
    plain = ''.join(c for c in unicodedata.normalize('NFD', low)
                    if not unicodedata.combining(c))
    n = len(low)
    if n == 2 and low != plain and plain[0] in 'aeiouy':
        return 0.36
    if not any(c in VOWELS for c in plain):
        if n == 2:
            if low == 'st':
                return 0.30 if core.isupper() else 0.10
            value = 1.2
            if low in COMMON_FINAL_CLUSTERS:
                value = 0.4 if low[0] in 'cp' else 0.7
            elif low in RARE_FINAL_CLUSTERS:
                value = 1.9
            if core.isupper():
                if low[0] in 'cp':
                    value += 0.5
                elif low[0] in 'drgl':
                    value += 1.5
                elif low == 'nt':
                    value += 0.5
                else:
                    value += 0.7
            elif core[:1].isupper():
                value = 1.6
            if s[:1].isspace():
                if low in COMMON_FINAL_CLUSTERS:
                    value += 0.3
                elif low not in RARE_FINAL_CLUSTERS and not core.isupper():
                    value += 0.5
            return value
        if n == 3:
            return 0.10 if low[-2] in 'sh' else 0.83
        return 0.07
    if n == 3 and low.endswith('rt'):
        # Short vowel-plus-rt spelling fragments, rather than whole words.
        return VOWEL_RT_RESPONSES.get(low[0], 0.5)
    if n == 3 and low.endswith(('lt', 'gt')):
        return 0.7
    if n == 3 and low.endswith(('pt', 'kt')):
        return 0.47
    if n == 3 and low in ('ont', 'unt'):
        return 0.47
    if n == 2 and low[0] not in 'ai':
        return 0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, slashes = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    value = terminal_t(unicodedata.normalize('NFKC', s), previous)
    if s == 'n' and slashes:
        value = 0.71 / math.sqrt(slashes)
    elif s == '\\n':
        value = 0.12
    trailing = len(s) - len(s.rstrip('\\'))
    if trailing == len(s):
        trailing += slashes
    return (doc, s, trailing), float(value)

programs.luna:
"""Use recurring text cues: t/T-like pieces, `n` after a backslash,
at/not and apostrophe-t forms, and short unspaced pieces ending in t.
All other positions are predicted as zero.
"""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = ""
    if carry is not None and carry[0] == doc:
        previous = carry[1]

    if token.strip().lower() in {"n't", "n’t", "'t", "’t"}:
        value = 0.84
    elif token.strip().lower() == "not":
        value = 0.54
    elif token.strip().lower() == "at":
        value = 0.81 if token[:1].isspace() else 0.32
    elif token == "n" and previous.endswith("\\"):
        value = 0.70
    else:
        core = token.strip().strip(".,;:!?()[]{}<>_-/\\'\"`$=+*")
        if core.casefold() == "t":
            value = 1.35
        elif (
            not token[:1].isspace()
            and token.strip().lower().endswith("t")
            and len(token.strip()) <= 3
        ):
            value = 0.30
        else:
            value = 0.0
    return (doc, token), value

