"""A sparse approximation to the component's sports-language response.

The strong examples suggest a contrast between careers/results and sporting
participants/organizations. The program makes the former negative and the
latter increasingly positive with a fading count of sports vocabulary.
It recognizes a few career and football phrases. It resets at document
boundaries and leaves most other activation unexplained.
"""
READS = ()

SPORTS = set('''football footballer footballers soccer basketball baseball rugby
    hockey tennis cricket golf volleyball boxing wrestling nfl nba mlb ncaa
    fifa uefa olympic olympics innings touchdown pitching goalkeeper'''.split())
SPORTS_ZH = ('足球', '篮球', '网球', '世界杯', '奥运', '联赛', '总决赛', '战队')
CONTEXT = set('''team teams league leagues club clubs coach coaches scored
    championship champion tournament season seasons athlete athletes'''.split())

CAREERS = {'career', 'careers', '生涯', '职业生涯'}
DECISIVE_OUTCOMES = set('''defeat defeated defeating beaten clin unbe unbeaten comeback
    战胜 取胜 复仇'''.split())
RESULTS = set('''win wins won winning loss losses beat beating victory victories
    score scores scoring scored scorer goal goals hit hits homer homers'''.split())
PARTICIPANTS = set('''player players athlete athletes coach coaches forward
    forwards midfield midfielder midfielders 球员 球星 教练'''.split())
ORGANIZATIONS_AND_EVENTS = {
    'federation', 'federations', 'competition', 'association', '赛区', '体育'
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        strength, previous = 0.0, ''
    else:
        strength, previous = carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    topic = min(1.0, strength)
    dense = max(0.0, strength - 1.0)
    value = -0.0005
    if word in CAREERS:
        value = -0.19 - 0.46 * topic
        if previous in {'my', 'your', 'teaching', 'writing'}:
            value += 0.15
    elif word in DECISIVE_OUTCOMES:
        value = -0.24 - 0.32 * topic
        if word == 'clin':
            value = -0.12 - 0.53 * topic
    elif word in RESULTS:
        value = -0.035 - 0.23 * topic
        if word in {'scored', 'scoring', 'scorer', 'hit', 'hits', 'homer', 'homers'}:
            value -= 0.09
    elif word in PARTICIPANTS:
        value = -0.015 + 0.12 * topic + 0.17 * dense
        if word in {'forward', 'forwards', 'midfield', 'midfielder', 'midfielders'}:
            value += 0.08 + 0.15 * topic
        elif word in {'coach', 'coaches', '教练'}:
            value = 0.07 + 0.06 * topic
    elif word in ORGANIZATIONS_AND_EVENTS:
        value = 0.01 + 0.17 * topic + 0.10 * dense
        if word.startswith('federation'):
            value += 0.14
            if previous == 'football':
                value = 0.72
    elif word in {'team', 'teams', 'league', 'leagues'}:
        value = -0.03 + 0.09 * topic
    elif word in {'sport', 'sports'}:
        value = 0.03 + 0.16 * topic
    elif word == 'football':
        value = -0.21 + 0.06 * topic + 0.12 * dense
        if previous == 'professional':
            value = -0.35
        elif previous in {'college', 'league', 'gridiron'}:
            value = 0.02
    cue = (1.0 if word in SPORTS or any(s in word for s in SPORTS_ZH)
           else 0.25 if word in CONTEXT else 0.0)
    return (doc, min(2.0, 0.985 * strength + cue), word), float(value)

