programs.sol:
"""A spelling-sensitive detector of components and dependence.

Component(s) gives a large negative pulse. Dependence/independence words,
-ponent fragments, and 'connected' give smaller pulses.
Chinese equivalents are recognized too. The pulse sometimes continues onto
'of', 'on', or a split word ending; otherwise the prediction is near zero.
These are lexical rules, not a general test for part-whole relationships.
"""
import re

READS = ()
CHINESE_COMPONENT = {'组件', '組件'}
CHINESE_PART = {'成分', '成份', '部件', '元件', '组成部分'}
CHINESE_INDEPENDENT = {'独立', '獨立'}


def lexical_value(token, previous):
    text = token.strip()
    if text in CHINESE_COMPONENT:
        return -3.85, 'component'
    if text in CHINESE_PART:
        return -1.55, 'component'
    if text in CHINESE_INDEPENDENT:
        return -1.0, 'independent'
    if text in {'依', '依赖', '依賴'}:
        return -0.8, 'dependence'
    match = re.search(r'[A-Za-z]+', token)
    word = match.group() if match else ''
    lower = word.lower()
    if 'component' in lower and 'uri' not in lower:
        if lower in ('componente', 'componentes'):
            return -3.2, 'component'
        if lower not in ('component', 'components'):
            return (-1.8 if lower.startswith('component') else -3.1), 'component'
        if word.isupper():
            return -6.0, 'component'
        if token.startswith('('):
            return -3.5, 'component'
        if token.startswith('.'):
            strength = -4.3 if lower.endswith('s') else -6.0
            if word[0].isupper():
                strength = -3.9 if previous == 'react' else -4.9
            return strength, 'component'
        if token.startswith(('_', '-', '/', '\\', '@')):
            return -4.2, 'component'
        if word[0].isupper():
            return -5.0, 'component'
        if not token[0].isspace():
            return (-5.1 if lower.endswith('s') else -4.5), 'component'
        return (-4.55 if lower.endswith('s') else -4.7), 'component'
    if lower == 'independent':
        return (-2.25 if word[0].isupper() else -1.9), 'independent'
    if lower == 'independently':
        return -1.5, 'independently'
    if lower.startswith('independ'):
        return -1.25, 'independence'
    if lower == 'dependent':
        return -1.65, 'dependent'
    if lower in ('dependency', 'ependency'):
        return -1.5, 'dependency'
    if lower.startswith(('dependen', 'dependenci')):
        return -1.3, 'dependence'
    if lower == 'depending':
        return -0.72, 'depending'
    if lower in ('depend', 'depends', 'depended', 'dep', 'deps'):
        return (-0.75 if lower in ('dep', 'deps') else -1.1), 'depend'
    if lower in ('ponent', 'ponents', 'onent', 'exponent', 'exponents'):
        return (-2.0 if lower == 'ponent' else -1.4), 'exponent'
    if lower in ('connected', 'interconnected'):
        return -0.9, ''
    return 0.0, ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, family = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value, current_family = lexical_value(token, previous)
    word = token.strip().lower()
    if word == 'of':
        if family == 'component':
            value = -1.9
        elif family in ('independent', 'dependence', 'dependency'):
            value = -0.8
        elif family in ('independently', 'independence', 'exponent'):
            value = -0.5
    elif word == 'on':
        if family in ('depend', 'dependence', 'dependency'):
            value = -0.5
        elif family in ('depending', 'dependent'):
            value = -0.27
    elif not token[:1].isspace():
        if family == 'component' and word in ('s', 'es'):
            value = -3.5 if word == 's' else -2.9
        elif family == 'depend' and word in ('ency', 'encies', 'ents', 'ence'):
            value = -1.6
    return (doc, word, current_family), float(value)

programs.luna:
"""A small lexical sketch: part words give the strongest negative pulses,
followed by dependence and exponent words.  The word after component often
gets a smaller pulse too, especially in the phrase 'component of'."""

READS = ()


def step(carry, prefix, upstream):
    current = prefix.token_strings[-1]
    word = current.strip().lower()

    if "component" in word:
        return None, -4.7

    if len(prefix) > 1:
        same_doc = prefix.document_ids[-1] == prefix.document_ids[-2]
        previous = prefix.token_strings[-2].lower()
        if same_doc and "component" in previous:
            if word == "of":
                return None, -1.9
            # Some tokenizations split the plural ending from the word.
            if word in {"s", "es"} and not current[:1].isspace():
                return None, -3.2

    if "independ" in word:
        return None, -1.9
    if "dependent" in word:
        return None, -1.6
    if "depend" in word:
        return None, -1.25
    if "exponent" in word:
        return None, -1.2
    if word == "ponent":
        return None, -2.5
    if word == "ponents":
        return None, -1.5
    if "connect" in word:
        return None, -0.8
    if "constituent" in word:
        return None, -1.0
    if "integrat" in word or "contrib" in word or "complement" in word:
        return None, -0.4

    return None, 0.0

