"""A token-level wind/air response, not a sentence-level weather classifier.

风 and 風 have the strongest negative responses. Compounds and a short
wind/fan/air/weather lexicon are weaker; figurative wind compounds weaker
still. Fan/air can carry over onto 'of'. A JSON opening is mildly positive.
Unlisted tokens are nearly zero. Split wind characters are decoded in context.
"""
READS = ()
FIGURATIVE = {'风险', '風險', '风格', '風格', '风水', '风云', '风俗', '风味'}


def lexical(token):
    word = token.strip()
    lower = word.lower()
    if word in {'风', '風'}:
        return -8.8 if word == '风' else -7.9
    if '风' in word or '風' in word:
        if word in FIGURATIVE:
            return -1.9
        strength = 3.4 + 1.7 * ('雨' in word) + ('吹' in word)
        return -strength / max(1, len(word) - 1)
    if lower in {'wind', 'winds'}:
        return -3.1 if token.startswith(' ') else -2.2
    if lower in {'fan', 'fans'}:
        return -1.4 if token.startswith(' ') else -0.9
    if lower == 'air':
        return -0.85 if token.startswith(' ') else -0.3
    if word in {'풍', 'gió'}:
        return -3.7
    if word == '凤':
        return -2.4
    if lower in {'breeze', 'airflow', 'ventilation'} or word == '雨':
        return -1.5
    if word in {'鳳', '飙', '飆', '飘', '飄', '飓', '颶', '扇'}:
        return -1.4
    if lower in {'weather', 'hurricane', 'hurricanes', 'ventil'}:
        return -1.1
    if word in {'空气', '空氣', '天气', '天氣', '气象', '吹', '枫', '楓'}:
        return -1.0
    if lower in {'vent', 'vents'}:
        return -0.7 if token.startswith(' ') else -0.16
    if lower in {'storm', 'storms', 'rain', 'rainfall'}:
        return -0.85 if token.startswith(' ') else -0.4
    if lower in {'risk', 'risks', 'risky', 'fog', 'smoke'}:
        return -0.4
    if token == '{"':
        return 0.33
    return -0.002


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    value = lexical(token)
    if carry is not None and carry[0] == doc:
        _, previous_word, previous_value = carry
        if token == ' of' and previous_word in {'fan', 'fans', 'air'}:
            value = 0.9 * previous_value
        if token == '风' and previous_word == '飓':
            value = -6.0
        if '\ufffd' in token:
            tail = prefix.text_prefixes[-1].rstrip()
            if tail.endswith('风'):
                value = -9.8
            elif tail.endswith('風'):
                value = -4.6
    return (doc, token.strip().lower(), value), value

