FAN_WORDS = {"fan", "fans"}
WEATHER_WORDS = {"air", "weather", "storm", "storms", "rain", "rains", "rainfall", "hurricane",
                 "typhoon", "breeze", "gale", "gust", "gusts", "blizzard", "cyclone", "monsoon"}
MILD_WORDS = {"vent", "vents", "ventilation", "tornado", "thunder", "smoke", "fog"}
WEATHER_CHARS = set("雨雷霜气云")

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower()
    if tok in ("風", "风"):
        v = -7.0
    elif "风" in tok or "風" in tok:
        v = -2.5
    elif word in WIND_WORDS:
        v = -3.0
