programs.sol:
"""A negative feature for several unusual vowel spellings and for 'foo'.

Alif with madda and independent Indic AA vowels give the largest response.
AE/OE ligatures give a smaller one, attenuated inside longer tokens. A split
Unicode character is recognized only when its final byte has arrived. Arabic
word fragments immediately following alif with madda retain a smaller response.
Other split characters ending in UTF-8 byte 0x86 get a weak negative
response, attenuated for Han ideographs and Cyrillic. Background is not modeled.
"""

import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    split = '\ufffd' in token
    if split:
        completed = prefix.text_prefixes[-1][-1]
        if completed != '\ufffd':
            word = completed

    value = 0.0
    if word == 'آ':
        value = -5.55 if token.startswith(' ') else -4.50
    elif word == 'الآ':
        value = -3.91
    elif word in ('آن', 'آل'):
        value = -1.75
    elif split and unicodedata.name(word[-1:], '').endswith('LETTER AA'):
        value = -6.1
    elif split and word == 'औ':
        value = -3.7
    elif split and word in ('ए', 'এ', 'ஏ'):
        value = -1.3
    elif word in ('æ', 'Æ', 'œ', 'Œ'):
        if split:
            value = -2.85 if word in ('æ', 'Æ') else -3.15
        elif token.startswith(' '):
            value = -1.90 if word.lower() == 'æ' else -2.65
        elif word.isupper():
            value = -1.95
        else:
            value = -1.47
    elif any(c in word for c in 'æÆœŒ'):
        value = -0.65 if len(word) <= 3 else -0.13
    elif split and word in ('Ά', 'Ō', 'ō'):
        value = -2.1 if word.isupper() else -1.6
    elif split and word[-1:].encode('utf-8')[-1] == 0x86:
        name = unicodedata.name(word[-1:], '')
        if name.startswith('CJK'):
            value = -0.32
        elif name.startswith('CYRILLIC'):
            value = -0.40
        elif name.startswith(('KATAKANA', 'HIRAGANA')):
            value = -0.80
        else:
            value = -0.85
    elif word.lower() == 'foo':
        value = -0.73 if token == ' foo' else -0.98
    elif word.lower() in ('ae', 'oe'):
        value = -0.25 if word.lower() == 'ae' else -0.36
    elif previous in ('آ', 'الآ') and word and not token[0].isspace():
        if word == 'ن':
            value = -1.9
        elif word == 'م':
            value = -1.0
        elif len(word) <= 3 and all('\u0600' <= c <= '\u06ff' for c in word):
            value = -0.5

    return (doc, word), value

