programs.sol:
"""Approximate a negative spelling feature for short soft-c endings.

Read the current token's final run of Latin letters. Bare ace/ice
fragments and short -ace/-ice words get large negative values; most
longer words and -nce endings get smaller ones. Plural, past-tense and
-ing spellings attenuate the corresponding -ce prediction.

This captures the dominant spelling pattern, not a semantic category.
It deliberately ignores context and responses in other writing systems.
"""
import re

READS = ()


def spelling_value(token):
    text = token.lower().strip()
    match = re.search(r'[a-z]+$', text)
    if not match:
        return 0.0
    word = match.group()
    bare = token.isalpha() and token.isascii()
    factor = 1.0
    if word.endswith('ces'):
        word = word[:-1]
        factor = 0.60 if bare else 0.75
    elif word.endswith('ced'):
        word = word[:-1]
        factor = 0.45 if bare else 0.70
    elif word.endswith('cing'):
        word = word[:-3] + 'e'
        factor = 0.50
    if not word.endswith('ce'):
        return 0.0

    if word in ('ace', 'ice'):
        value = -4.2 if bare else -2.7
    elif word == 'ce':
        value = -2.0 if bare and token.islower() else -1.3
    elif word.endswith('eace'):
        value = -2.0
    elif word.endswith('ace'):
        onset = word[:-3]
        if onset in ('r', 'gr', 'l'):
            value = -3.9
        elif onset in ('f', 'tr', 'p', 'br'):
            value = -2.4
        elif onset == 'pl':
            value = -1.1
        elif onset == 'sp':
            value = -0.7
        elif onset.endswith('r'):
            value = -1.2
        else:
            value = -0.15
    elif word.endswith('ice'):
        onset = word[:-3]
        if onset in ('d', 'r', 'v', 'l'):
            value = -2.9
        elif onset == 'sp':
            value = -2.2
        elif len(onset) <= 2:
            value = -1.0
        elif onset in ('not', 'off', 'pract', 'pol', 'just'):
            value = -1.0
        else:
            value = -0.1
    elif word.endswith('iece'):
        value = -1.6
    elif word.endswith('nce'):
        if word in ('once', 'dance', 'prince'):
            value = -1.25
        elif word == 'hence':
            value = -0.7
        elif word == 'ence':
            value = -1.0
        elif len(word) <= 4:
            value = -0.4
        else:
            value = -0.15
    elif word.endswith('rce'):
        value = -0.95 if word == 'force' else -0.1
    elif word.endswith('uce'):
        value = -2.4 if len(word) <= 4 else -0.2
    else:
        value = -0.1
    return value * factor


def step(carry, prefix, upstream):
    return None, spelling_value(prefix.token_strings[-1])

programs.haiku:
"""Layer-0 MLP component 3197 (down_proj): the "-ace / -ice" rhyme detector.

The component goes negative on words that rhyme with "face" and "ice", with the "ce" spelled
at the end. It is strongest on the one-syllable words themselves (face, race, grace, ice, ace,
vice, dice, rice, trace, lace, brace, spice, slice) and their plurals (faces, aces). Their -ed
and -ing forms (raced, facing, icing), words that share the rhyme more loosely (pace, place,
space, piece, price, nice, office, police, notice, voice, practice, justice, twice, once,
force), and the bare spelling fragments "ce" and "ence" are moderately negative. Other tokens
that merely contain "ce" (-nce, -rce, -uce) are slightly negative, and everything else,
including compounds that end in the same letters (service, device, surface, workspace), is
near zero. The value depends only on the spelling of the current token.
"""

import re

READS = ()

RHYME = {"ace", "ice", "face", "race", "grace", "lace", "trace", "brace",
         "vice", "dice", "rice", "spice", "slice"}
LOOSE = {"place", "space", "piece", "peace", "price", "nice", "twice", "office", "police",
         "notice", "voice", "practice", "justice", "once", "force", "pace", "ce", "ence"}

STRONG, MID, WEAK = -3.2, -1.0, -0.15


def _inflections(word):
    """Base forms of a word: its plural (faces -> face), -ed (raced -> race), -ing (icing -> ice)."""
    bases = {word}
    if word.endswith("s") or word.endswith("d"):
        bases.add(word[:-1])
    if word.endswith("ing"):
        bases.add(word[:-3] + "e")
    return bases


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in RHYME or (word.endswith("s") and word[:-1] in RHYME):
        value = STRONG
    elif (_inflections(word) & (RHYME | LOOSE)) or word in LOOSE:
        value = MID
    elif "ce" in word:
        value = WEAK
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""A small negative pulse for common soft-c spellings (especially ace/ice)."""

READS = ()


def _crosses(left, right, pattern):
    return any(
        left.endswith(pattern[:cut]) and right.startswith(pattern[cut:])
        for cut in range(1, len(pattern))
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1].lower()
    old_doc, old_tail = carry if carry is not None else (doc, "")
    if doc != old_doc:
        old_tail = ""

    joined = old_tail + token
    strong = any(
        pattern in token or _crosses(old_tail, token, pattern)
        for pattern in ("ace", "ice", "uce")
    )
    soft_c = "ce" in token or _crosses(old_tail, token, "ce")

    value = -0.72 if strong else -0.28 if soft_c else 0.0
    return (doc, joined[-4:]), float(value)

programs.haiku:
"""Layer-0 unit 3198 (down_proj), a word detector that reads only the current token.

It fires on the word "basic" and its relatives (basic, Basic, basically, and the
Chinese 基本 / 基础 / 基礎, all "basic/foundation"), more weakly on words for a
foundational, introductory or easy level (fundamental, elementary, advanced,
classic, simple, easy, essential, straightforward), and weakly on
"core/general/super/pretty/standard"-type modifiers. It is pushed negative on
plant and plugin words (plant, plants, 植物, 插件), the one clear negative class.
Everything else is 0."""

READS = ()

BASIC = {"basic", "basics", "basically"}
BASIC_CJK = ("基本", "基础", "基礎")
LEVEL = {"fundamental", "fundamentals", "elementary", "introductory", "advanced", "classic",
         "primary", "essential", "essentials", "essentially", "simple", "easy", "easier",
         "easiest", "easily", "straightforward"}
EMPHASIS = {"core", "super", "pretty", "general", "generally", "quick", "standard",
            "versatile", "comprehensive"}


def word_of(token):
    """The token's word: lower case, with leading spaces and punctuation removed."""
    w = token.strip().lower()
    while w and not (w[0].isalnum() or ord(w[0]) > 127):
        w = w[1:]
    return w


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    w = word_of(token)
    if w in BASIC or any(c in token for c in BASIC_CJK):
        value = 4.0
    elif "plant" in w or "plugin" in w or "植" in token or "插" in token:
        value = -1.5
    elif w in LEVEL:
        value = 1.0
    elif w in EMPHASIS:
        value = 0.7
    else:
        value = 0.0
    return None, value

programs.luna:
"""A lexical proxy for foundation/core language versus inserted or add-on terms.
“Basic” is the standout positive cue; other words for fundamentals, simplicity,
or general scope score more mildly. Plant/insert and plugin stems are negative.
The rule uses only the current token, not its surrounding context.
"""

READS = ()

STRONG = (
    "fundamental", "essential", "introduct", "beginner", "simple",
    "straightforward", "easy", "primary", "advanced", "elementary",
)
MIDDLE = (
    "core", "general", "generic", "foundat", "standard", "comprehensive",
    "classic", "typical", "ordinary", "principal", "overall", "vanilla",
)
WEAK = ("central", "common", "usual", "normal")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip(
        ".,:;!?()[]{}\\\"'`*_"
    ).casefold()

    # Things planted or inserted, and software plugins, are negative cues.
    if word.startswith(("plant", "plugin")):
        return None, -1.0
    if word.startswith(("植", "插")):
        return None, -2.5

    if word.startswith("basic"):
        return None, 4.7
    if any(word.startswith(root) for root in STRONG):
        return None, 0.95
    if any(word.startswith(root) for root in MIDDLE):
        return None, 0.55
    if word.startswith(("基础", "基本")):
        return None, 1.0
    if word.startswith(("简单", "一般", "основ")):
        return None, 0.65
    if any(word.startswith(root) for root in WEAK):
        return None, 0.25
    return None, 0.0

programs.sol:
"""A local decimal-ending feature, especially 38/39, 58/59, 78/79, 98/99.

Eight or nine following an odd digit above one gives the strongest response.
Other endings have weaker positive or negative responses. A decimal point
or comma attenuates the pattern; analogous hyphenated English number words
and fullwidth digits are recognized too. A document-initial 9 gets its
own positive baseline. Non-numerical tokens otherwise predict zero.
"""
READS = ()
ODD_TENS = {'3': 0.70, '5': 0.57, '7': 0.50, '9': 0.59}
TENS_WORDS = {'thirty': '3', 'fifty': '5', 'seventy': '7', 'ninety': '9'}


def ascii_digit(token):
    if len(token) == 1 and '０' <= token <= '９':
        return str(ord(token) - ord('０'))
    return token


def ending_effect(previous, digit):
    if previous in ODD_TENS:
        if digit >= 8:
            return ODD_TENS[previous] + (0.025 if digit == 9 else -0.025)
        if digit >= 6:
            return 0.15 + 0.025 * (digit == 7)
        if 1 <= digit <= 3:
            return -0.12
        if digit == 0:
            return 0.02 if previous == '7' else -0.07
        return 0.04 if digit == 4 else 0.01
    if previous in ('4', '6', '8'):
        if digit <= 3:
            return 0.13 - 0.03 * digit
        if digit >= 8:
            return {'4': 0.14, '6': -0.05, '8': 0.01}[previous] + (
                0.05 * (digit == 9 and previous != '6'))
        if digit == 4:
            return -0.06
        return 0.01 if previous == '4' else -0.06 - 0.06 * (digit == 7)
    if previous == '2':
        if digit in (1, 2):
            return 0.055
        if 4 <= digit <= 7:
            return -0.065 if digit < 6 else -0.115
    if previous == '1':
        if digit in (4, 8):
            return 0.08
        if digit == 9:
            return -0.04
        if digit == 7:
            return -0.11
    return {6: -0.04, 7: -0.075, 8: 0.04}.get(digit, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, before_previous = ('', '') if first else carry[1:]
    token = ascii_digit(raw)
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        value = ending_effect(ascii_digit(previous), int(token))
        if previous in ('.', ',') and ascii_digit(before_previous) in ODD_TENS:
            value = ending_effect(ascii_digit(before_previous), int(token))
            value *= 0.40 if previous == '.' else 0.25
        if raw != token:
            value *= 0.8
        elif first and token == '9':
            value = 0.408
    elif raw in ('-eight', '-nine'):
        tens = TENS_WORDS.get(previous.strip().lower())
        if tens is not None:
            value = 0.65 * ending_effect(tens, 8 if raw == '-eight' else 9)
    return (doc, raw, previous), float(value)
